/**
 * What every primitive of audio/ui shares and the kernel does not do: parts
 * named in kebab case, a value reported as `onValueChange` and
 * `onValueCommitted`, one pointer gesture at a time, and a native input
 * hidden from sight. The primitives import it from `../primitive`.
 */
import {
  bindDrag,
  type ChangeSource,
  createChange,
  definePrimitive as definePrimitiveOf,
  dispatch,
  type PointerSample,
  type PrimitiveContext,
} from "@ui-sdk/core";

/** A boolean as a data attribute: present and empty, or absent. */
export const flag = (on: boolean) => (on ? "" : undefined);

/** What a change reports to `onValueChange`, beside the value. */
export interface ChangeDetails {
  cancel: () => void;
  event?: Event;
  /** The point or segment that moved, for a control that has several. */
  index?: number;
  reason: string;
  source?: string;
}

/** What a commit reports to `onValueCommitted`, beside the value. */
export interface CommitDetails {
  event?: Event;
  index?: number;
  reason: string;
}

/** How a native input is hidden while it keeps the focus, the keys and the name. */
export const VISUALLY_HIDDEN = {
  border: "0",
  "clip-path": "inset(50%)",
  height: "1px",
  margin: "-1px",
  overflow: "hidden",
  padding: "0",
  position: "absolute",
  "white-space": "nowrap",
  width: "1px",
};

/**
 * How a change came about, when its event says. The kernel reads it from
 * input it tracks, so the first interaction would report "programmatic"
 * without this. With no event, the kernel decides, and an agent's change
 * stays the agent's.
 */
export function sourceOf(event?: Event): ChangeSource | undefined {
  if (typeof PointerEvent !== "undefined" && event instanceof PointerEvent) {
    return event.pointerType === "touch" || event.pointerType === "pen"
      ? event.pointerType
      : "mouse";
  }
  if (event instanceof MouseEvent) {
    return "mouse";
  }
  if (event instanceof KeyboardEvent) {
    return "keyboard";
  }
}

/** A change or a commit's details: the reason, the event, and who caused it when the event says. */
function detailsOf(reason: string, event?: Event, extra?: object) {
  const source = sourceOf(event);
  return { event, reason, ...(source ? { source } : {}), ...extra };
}

/**
 * How a primitive whose state holds a `value` reports it: `report` fires
 * `onValueChange` and keeps the value unless an app refused it, `commit`
 * fires `onValueCommitted`, and `setAtOnce` does both, for a change that is
 * over as soon as it is made (a key, a typed value, the wheel, a reset). It
 * skips a value `same` finds equal to the one `displayed` shows; with no
 * `same`, every value is reported, even an unchanged one. `extra` goes into
 * the details, such as the `index` of the point that moved.
 */
export function createReporter<State extends { value: Value }, Value>(
  context: PrimitiveContext<any, State, any>,
  displayed: (state: State) => Value,
  same?: (a: Value, b: Value) => boolean
) {
  const change = createChange(context);
  const state = () => context.store.get() as State;
  const commit = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    dispatch(
      context,
      "onValueCommitted",
      value,
      detailsOf(reason, event, extra)
    );
  };
  const report = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) =>
    change("value", value as never, detailsOf(reason, event, extra) as never);
  const setAtOnce = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    if (same?.(value, displayed(state()))) {
      return;
    }
    if (report(value, reason, event, extra)) {
      commit(value, reason, event, extra);
    }
  };
  return { commit, report, setAtOnce, state };
}

/** Two numbers as one text: a comma between them, or a semicolon where the comma is the decimal mark. */
export function formatPair(formatter: Intl.NumberFormat, a: number, b: number) {
  const decimalComma = formatter
    .formatToParts(1.5)
    .some((part) => part.type === "decimal" && part.value === ",");
  return `${formatter.format(a)}${decimalComma ? "; " : ", "}${formatter.format(b)}`;
}

/** Where in an interval a curve is checked against its chord, how many times an interval may be halved, and a ceiling on the vertices of one curve. */
const PROBES = [0.25, 0.5, 0.75];
const MAX_DEPTH = 8;
const MAX_SAMPLES = 4096;

/**
 * The vertices of a polyline that draws `f(t)` for `t` from 0 to 1 without
 * straying more than `tolerance` from it: it starts from `grid` and halves
 * every interval whose curve leaves its chord. `width` is how wide `t` from 0
 * to 1 spans in the box the curve is drawn in.
 */
export function adaptiveSamples(
  f: (t: number) => number,
  grid: readonly number[],
  tolerance: number,
  width = 1
) {
  const samples: [number, number][] = [];
  let budget = MAX_SAMPLES - grid.length;
  const refine = (
    from: number,
    start: number,
    to: number,
    end: number,
    depth: number
  ) => {
    if (depth >= MAX_DEPTH || budget <= 0) {
      return;
    }
    let stray = 0;
    let middle = Number.NaN;
    for (const probe of PROBES) {
      const value = f(from + (to - from) * probe);
      stray = Math.max(
        stray,
        Math.abs(value - (start + (end - start) * probe))
      );
      if (probe === 0.5) {
        middle = value;
      }
    }
    const slope = (end - start) / ((to - from) * width);
    if (stray / Math.sqrt(1 + slope * slope) <= tolerance) {
      return;
    }
    const half = (from + to) / 2;
    budget -= 1;
    refine(from, start, half, middle, depth + 1);
    samples.push([half, middle]);
    refine(half, middle, to, end, depth + 1);
  };
  const values = grid.map(f);
  grid.forEach((t, index) => {
    const value = values[index] ?? 0;
    samples.push([t, value]);
    const next = grid[index + 1];
    if (next !== undefined) {
      refine(t, value, next, values[index + 1] ?? 0, 0);
    }
  });
  return samples;
}

/**
 * What a change reports: why it happened (`reason`), the event behind it,
 * and `cancel()` to refuse the change.
 */
export interface ChangeEventDetails<Reason extends string, E extends Event> {
  cancel: () => void;
  event: E;
  readonly isCanceled: boolean;
  reason: Reason;
}

/** What a commit reports once a gesture ends: why it happened and the event behind it. */
export interface CommitEventDetails<Reason extends string, E extends Event> {
  event: E;
  reason: Reason;
}

/** The details of a change for `reason` and `event`, with `cancel()` to refuse it. */
export function createChangeEventDetails<
  Reason extends string,
  E extends Event,
>(reason: Reason, event: E): ChangeEventDetails<Reason, E> {
  let canceled = false;
  return {
    cancel: () => {
      canceled = true;
    },
    event,
    get isCanceled() {
      return canceled;
    },
    reason,
  };
}

/**
 * One pointer at a time on a control: while one drags, a press from another is
 * ignored, and the same pointer pressing again means its release was missed,
 * so the drag it left ends there. Moves arrive at most once per frame, each
 * with where the pointer was at the last one.
 */
export function createPointerLock() {
  type Held = {
    end: (event: PointerEvent) => void;
    pointerId: number;
    stop: () => void;
  };
  let held: Held | null = null;
  return {
    claim: (event: PointerEvent) => {
      if (!held) {
        return true;
      }
      if (held.pointerId !== event.pointerId) {
        return false;
      }
      const stale = held;
      held = null;
      stale.stop();
      stale.end(event);
      return true;
    },
    follow: (
      target: Element,
      down: PointerEvent,
      move: (event: PointerEvent, from: { x: number; y: number }) => void,
      end: (event: PointerEvent) => void
    ) => {
      let last = { x: down.clientX, y: down.clientY };
      const entry: Held = {
        end,
        pointerId: down.pointerId,
        stop: () => undefined,
      };
      held = entry;
      entry.stop = bindDrag(target as HTMLElement, down, {
        onEnd: (event) => {
          if (held === entry) {
            held = null;
          }
          end(event);
        },
        onMove: ({ event }) => {
          const from = last;
          last = { x: event.clientX, y: event.clientY };
          move(event, from);
        },
      });
    },
  };
}

/**
 * A value that changes outside the framework, in the shape of an external
 * store: `subscribe` registers a listener called on each change, and
 * `getSnapshot` returns the current value. What a primitive's `source` reads
 * from, so that following a signal costs no render.
 */
export interface Source<Value> {
  getSnapshot: () => Value;
  subscribe: (listener: () => void) => () => void;
}

/** A source that also takes values: what `createSource` returns. */
export interface WritableSource<Value> extends Source<Value> {
  /** Publishes a value. Subscribers are told every time, so the same array, updated in place, can be published again. */
  set: (value: Value) => void;
}

/**
 * A source you push to yourself, from an audio callback, a WebSocket, a worker
 * or a test: call `set` with each new reading, and whatever reads the source
 * follows.
 */
export function createSource<Value>(initial: Value): WritableSource<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    getSnapshot: () => value,
    set: (next) => {
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

/** A value the primitive holds and its parts read outside any render. */
export interface Store<Value> {
  get: () => Value;
  set: (next: Value) => void;
  subscribe: (listener: () => void) => () => void;
}

/** A store holding `initial`: `set` tells every listener, unless the value is the same one. */
export function createStore<Value>(initial: Value): Store<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next) => {
      if (Object.is(next, value)) {
        return;
      }
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/** What a gesture hears, from the press that started it to its release. */
export interface GestureHandlers<Data> {
  /** The pointer lifted, or the browser took it over (`canceled`). */
  onEnd: (event: PointerEvent, data: Data, canceled: boolean) => void;
  /** At most once per frame, with the latest pointer event. */
  onMove: (event: PointerEvent, data: Data, sample: PointerSample) => void;
}

/**
 * A primitive's pointer gestures, one at a time. Call `accepts` first, before
 * the primitive's own guards: another pointer pressing while a gesture runs
 * is refused, so a second finger does not take the gesture over, and the
 * same pointer pressing again means its release was missed, so its gesture
 * ends there, through `onStale`. A gesture carries `data` of its own, read
 * back by `active`, and stops when the primitive is destroyed.
 */
export function createGestures<Data>(context: {
  onDestroy: (cleanup: () => void) => void;
}) {
  type Running = { data: Data; pointerId: number; stop: () => void };
  let running: Running | null = null;
  context.onDestroy(() => running?.stop());
  return {
    /** Whether `event` may start a gesture, ending a stale one of the same pointer first. */
    accepts(event: PointerEvent, onStale?: (data: Data) => void) {
      const stale = running;
      if (!stale) {
        return true;
      }
      if (stale.pointerId !== event.pointerId) {
        return false;
      }
      running = null;
      stale.stop();
      onStale?.(stale.data);
      return true;
    },
    /** The data of the gesture that runs, if any. */
    active: () => running?.data ?? null,
    /** Follows the press on `el` until it lifts. */
    start(
      el: HTMLElement,
      event: PointerEvent,
      data: Data,
      handlers: GestureHandlers<Data>
    ) {
      running?.stop();
      const entry: Running = {
        data,
        pointerId: event.pointerId,
        stop: () => undefined,
      };
      running = entry;
      entry.stop = bindDrag(el, event, {
        onEnd: (end, canceled) => {
          if (running === entry) {
            running = null;
          }
          handlers.onEnd(end, data, canceled);
        },
        onMove: (sample) => handlers.onMove(sample.event, data, sample),
      });
    },
  };
}

const KEBAB = /([a-z0-9])([A-Z])/g;
const kebab = (name: string) => name.replace(KEBAB, "$1-$2").toLowerCase();

/**
 * The part a primitive draws names itself in `data-slot`, in kebab case
 * (`xypad-input-x`, `piano-roll-note`), the names the styles and the docs
 * select: the kernel writes the slot's key as it is (`xypad-inputX`). A
 * component that gives its own name to a part (`timeline-time-selection`)
 * keeps it.
 */
function nameSlots(name: string, slots: Record<string, any>) {
  const prefix = kebab(name);
  for (const [key, definition] of Object.entries(slots)) {
    const fallback = key === "root" ? prefix : `${prefix}-${kebab(key)}`;
    const { attrs } = definition;
    definition.attrs = (state: unknown, context: { props?: object }) => ({
      ...attrs?.(state, context),
      "data-slot":
        (context.props as Record<string, string> | undefined)?.["data-slot"] ??
        fallback,
    });
    definition.props = { ...definition.props, "data-slot": "string" };
  }
  return slots;
}

/** `definePrimitive` of the kernel, with the parts named in kebab case and a `data-slot` that can be given. */
export const definePrimitive = ((options: any) =>
  definePrimitiveOf({
    ...options,
    slots: (slot: unknown) => nameSlots(options.name, options.slots(slot)),
  })) as typeof definePrimitiveOf;

import {
  createChange,
  css,
  dispatch,
  type PrimitiveInstance,
  type PropSpec,
  type SlotDefinition,
} from "@ui-sdk/core";
import { isBlackKey, pitchName } from "../pitch";
import {
  type ChangeDetails,
  type CommitDetails,
  definePrimitive,
  flag,
  sourceOf,
  VISUALLY_HIDDEN,
} from "../primitive";
import {
  createPianoRollController,
  type PianoRollBand,
  type PianoRollController,
  type PianoRollSnapshot,
} from "./controller";
import {
  type Note,
  type NoteId,
  type NoteLevel,
  selectionSpan,
  spatialOrder,
} from "./edits";
import type { RollScale, Rows } from "./rows";

export type { ChangeDetails, CommitDetails } from "../primitive";
export type { Note, NoteId, NoteLevel } from "./edits";
export type { RollScale } from "./rows";

/**
 * The piano roll, over its controller (`controller.ts`): the notes and their
 * selection, drawing, moving, resizing, selecting with a marquee, velocity
 * and the commands on the keys, all stay in the controller; the edits it
 * makes are in `edits.ts`, the rows in `rows.ts`.
 *
 * The roll sits on a timeline but has no provider to read it from: it takes
 * the timeline's duration, grid, zoom and playback position as options, which
 * are the values you give the timeline.
 */

/** A live playback position: what it holds now, and a way to hear it change. */
export interface PositionSource {
  getSnapshot: () => number;
  subscribe: (listener: () => void) => () => void;
}

export const UNIT_PROPERTY = "--timeline-unit";
export const OFFSET_PROPERTY = "--timeline-offset";
export const LENGTH_PROPERTY = "--timeline-length";
export const ROWS_PROPERTY = "--piano-roll-rows";
export const ROW_PROPERTY = "--piano-roll-row";
export const VELOCITY_PROPERTY = "--piano-roll-velocity";
export const CHANCE_PROPERTY = "--piano-roll-chance";
export const DEVIATION_PROPERTY = "--piano-roll-deviation";
export const LEVEL_PROPERTY = "--piano-roll-level";

const formatPosition = (value: number) => String(Math.round(value * 100) / 100);

const describeNote = (note: Note) =>
  `${pitchName(note.pitch)}, ${formatPosition(note.start)} to ${formatPosition(note.start + note.length)}`;

const describeVelocity = (velocity: number) => `${Math.round(velocity * 100)}%`;

/** Why a pitch sounds or stops: a key pressed or glided over, the keyboard, or a note drawn, picked up or moved. */
export type RollNoteReason = "draw" | "drag" | "glide" | "keyboard" | "press";

/** What a pitch about to sound reports. */
export interface RollNoteOnDetails {
  cancel: () => void;
  event?: Event;
  reason: RollNoteReason;
  source?: string;
  /** How hard it sounds, from 0 to 1. */
  velocity: number;
}

/** What a pitch that stops reports. */
export interface RollNoteOffDetails {
  event?: Event;
  reason: RollNoteReason;
}

export interface PianoRollPrimitiveOptions {
  /** Pitches sounding from outside: they light up their rows and keys. */
  activePitches?: readonly number[];
  createNoteId?: () => NoteId;
  defaultSelection?: readonly NoteId[];
  defaultValue?: readonly Note[];
  disabled?: boolean;
  drawStyle?: "paint" | "stretch";
  /** The timeline's length, in its units. @default 1 */
  duration?: number;
  folded?: boolean | "scale";
  getNoteLabel?: (note: Note) => string;
  maxPitch?: number;
  minLength?: number;
  minPitch?: number;
  mode?: "draw" | "select";
  /** A pitch stops sounding, from a key, a note or a gesture on the grid. */
  onNoteOff?: (pitch: number, details: RollNoteOffDetails) => void;
  /** A pitch is about to sound, from a key, a note or a gesture on the grid: `details.cancel()` keeps it from. */
  onNoteOn?: (pitch: number, details: RollNoteOnDetails) => void;
  onSelectionChange?: (
    selection: readonly NoteId[],
    details: ChangeDetails
  ) => void;
  onValueChange?: (value: Note[], details: ChangeDetails) => void;
  onValueCommitted?: (value: Note[], details: CommitDetails) => void;
  /** The playback position, in the timeline's units. */
  position?: number;
  scale?: RollScale | null;
  selection?: readonly NoteId[];
  snapOffset?: number;
  snapPoints?: readonly number[];
  snapStep?: number;
  /** A live playback position, read when a gesture needs it. */
  source?: PositionSource;
  step?: number;
  value?: readonly Note[];
  /** The timeline's zoom, in px per unit; `null` while it fits its lane. */
  zoom?: number | null;
}

export interface PianoRollState {
  duration: number;
  /** Names a note for assistive technology. */
  getNoteLabel: ((note: Note) => string) | undefined;
  selection: readonly NoteId[];
  source: PositionSource | undefined;
  /** The notes the roll holds. */
  value: readonly Note[];
  view: PianoRollSnapshot;
  zoom: number | null;
}

/** What every part reads of the roll. */
export interface PianoRollPublicState {
  disabled: boolean;
  editing: boolean;
  folded: boolean;
  mode: "draw" | "select";
}

interface PartProps {
  id?: string;
}

/** The props of the parts that belong to a note. */
export interface NoteRef extends PartProps {
  /** The id of the note it belongs to. */
  note: NoteId;
}

export interface NotePublicState extends PianoRollPublicState {
  muted: boolean;
  selected: boolean;
}

export interface NoteEdgeState extends NotePublicState {
  edge: "end" | "start";
}

export interface RowPublicState extends PianoRollPublicState {
  active: boolean;
  color: "black" | "white";
  inScale: boolean;
  octave: boolean;
  outOfScale: boolean;
  scaleRoot: boolean;
}

export interface NotesPublicState extends PianoRollPublicState {
  /** The notes in reading order. */
  notes: readonly Note[];
}

export interface RowsPublicState extends PianoRollPublicState {
  /** The pitches drawn, highest first. */
  pitches: readonly number[];
}

/** What a key of the keyboard beside the roll reports when it sounds, as a piano reports it: the event can be missing. */
export interface KeyOnDetails {
  cancel: () => void;
  event?: Event;
  reason: string;
  source?: string;
  velocity?: number;
}

/** What a key reports when it is released. */
export interface KeyOffDetails {
  event?: Event;
  reason: string;
}

export interface KeysPublicState extends PianoRollPublicState {
  /** The pitches sounding. */
  active: readonly number[];
  /** Silences a pitch from a key. */
  keyOff: (pitch: number, details: KeyOffDetails) => void;
  /** Auditions a pitch from a key. */
  keyOn: (pitch: number, details: KeyOnDetails) => void;
  pitches: readonly number[];
}

const keyCallsOf = new WeakMap<
  PianoRollController,
  Pick<KeysPublicState, "keyOff" | "keyOn">
>();

/** The calls of the keys, made once for a controller so that the state stays equal between renders. */
function keyCalls(controller: PianoRollController) {
  let calls = keyCallsOf.get(controller);
  if (!calls) {
    calls = {
      keyOff: (pitch, details) =>
        controller.keyOff(
          pitch,
          details as Parameters<PianoRollController["keyOff"]>[1]
        ),
      keyOn: (pitch, details) => {
        // The controller reads Shift from the event; a piano's key may report none.
        details.event ??= new Event(details.reason);
        controller.keyOn(
          pitch,
          details as Parameters<PianoRollController["keyOn"]>[1]
        );
      },
    };
    keyCallsOf.set(controller, calls);
  }
  return calls;
}

export interface VelocityProps extends NoteRef {
  getAriaValueText?: (velocity: number) => string;
  level?: NoteLevel;
}

export interface VelocityLaneProps extends PartProps {
  level?: NoteLevel;
}

export interface PianoRollApi {
  controller: PianoRollController;
  /** The order the notes were in when a gesture began: they keep their places in the DOM while it lasts. */
  frozen: { ids: NoteId[] | null };
  /** The grid element, once it binds. */
  grid: { el: HTMLElement | null };
  internal: { keyOf: (value: unknown) => string };
  /** The note elements, by id. */
  noteEls: Map<string, HTMLElement>;
  /** Gives the focus to what a gesture asked for, once it is mounted. */
  settleFocus: () => void;
}

type Slot<Props, Public = PianoRollPublicState> = SlotDefinition<
  PianoRollState,
  PianoRollApi,
  Props,
  Public
>;

/** The roll's slots, by name. */
export type PianoRollSlots = {
  grid: Slot<PartProps>;
  keys: Slot<PartProps, KeysPublicState>;
  marquee: Slot<PartProps>;
  note: Slot<NoteRef, NotePublicState>;
  noteEnd: Slot<NoteRef, NoteEdgeState>;
  noteStart: Slot<NoteRef, NoteEdgeState>;
  notes: Slot<PartProps, NotesPublicState>;
  root: Slot<PartProps>;
  row: Slot<PartProps & { pitch: number }, RowPublicState>;
  rows: Slot<PartProps, RowsPublicState>;
  selectionSpan: Slot<PartProps>;
  stretchEnd: Slot<PartProps, PianoRollPublicState & { edge: "end" | "start" }>;
  stretchStart: Slot<
    PartProps,
    PianoRollPublicState & { edge: "end" | "start" }
  >;
  velocity: Slot<VelocityProps, NotePublicState>;
  velocityInput: Slot<VelocityProps, object>;
  velocityLane: Slot<
    VelocityLaneProps,
    PianoRollPublicState & { level: NoteLevel }
  >;
};

/** The type of `pianoRoll`, written out so a declaration can print it. */
export interface PianoRollPrimitive {
  options: Record<string, PropSpec> | undefined;
  slots: PianoRollSlots;
  (
    initialOptions: PianoRollPrimitiveOptions & { id: string }
  ): Omit<PrimitiveInstance, "api" | "get" | "types"> & {
    api: PianoRollApi;
    get: () => PianoRollState;
    types: {
      api: PianoRollApi;
      options: PianoRollPrimitiveOptions;
      slots: PianoRollSlots;
      state: PianoRollState;
    };
  };
}

/** The timeline the controller reads, from the options. */
function timelineOf(options: PianoRollPrimitiveOptions) {
  const duration = options.duration ?? 1;
  const snapStep = options.snapStep ?? 0;
  return {
    duration,
    grid: {
      offset: options.snapOffset ?? 0,
      points: options.snapPoints,
      step: snapStep,
    },
    position: () => options.source?.getSnapshot() ?? options.position ?? 0,
    step: options.step ?? (snapStep > 0 ? snapStep : duration / 100),
    zoom: options.zoom ?? null,
  };
}

const unitLength = (zoom: number | null, duration: number) =>
  zoom === null ? `calc(100% / ${duration > 0 ? duration : 1})` : `${zoom}px`;

const placedAt = (value: number) => ({
  [OFFSET_PROPERTY]: String(value),
  left: `calc(var(${UNIT_PROPERTY}) * var(${OFFSET_PROPERTY}))`,
  position: "absolute",
});

const placedOver = (start: number, length: number) => ({
  ...placedAt(start),
  [LENGTH_PROPERTY]: String(length),
  width: `calc(var(${UNIT_PROPERTY}) * var(${LENGTH_PROPERTY}))`,
});

const placedOnRow = (row: number) => ({
  [ROW_PROPERTY]: String(row),
  height: `calc(100% / var(${ROWS_PROPERTY}))`,
  position: "absolute",
  top: `calc(100% * var(${ROW_PROPERTY}) / var(${ROWS_PROPERTY}))`,
});

/** What makes a lane of a surface the roll draws on: the unit its parts are placed with. */
const laneStyle = (state: PianoRollState) => ({
  [UNIT_PROPERTY]: unitLength(state.zoom, state.duration),
  contain: "layout style",
  "overflow-x": "clip",
  position: "relative",
  ...(state.zoom === null
    ? {}
    : { "min-width": `${state.duration * state.zoom}px` }),
});

const publicOf = (state: PianoRollState): PianoRollPublicState => ({
  disabled: state.view.disabled,
  editing: state.view.editing,
  folded: state.view.folded,
  mode: state.view.mode,
});

const stateAttrs = (state: PianoRollState) => ({
  "data-disabled": flag(state.view.disabled),
  "data-editing": flag(state.view.editing),
  "data-folded": flag(state.view.folded),
  "data-mode": state.view.mode,
});

const ids = new WeakMap<object, Map<string, NoteId>>();

/** The id a note is known by: a part carries it as text, a note's own may be a number. */
function idOf(state: PianoRollState, key: NoteId): NoteId {
  let known = ids.get(state.view);
  if (!known) {
    known = new Map(state.view.notes.map((note) => [String(note.id), note.id]));
    ids.set(state.view, known);
  }
  return known.get(String(key)) ?? key;
}

const noteOf = (state: PianoRollState, key: NoteId) =>
  state.view.noteById.get(idOf(state, key));

export const pianoRoll: PianoRollPrimitive = definePrimitive({
  agent: { actions: ["setValue"] },
  api: (context) => {
    const options = () => context.options() as PianoRollPrimitiveOptions;
    const change = createChange(context);
    const noteEls = new Map<string, HTMLElement>();
    const grid = { el: null as HTMLElement | null };
    // Focus that has to wait for the notes to render: a note just added, or where focus goes once the focused note is removed.
    let pending: { target: NoteId | null } | null = null;
    const settleFocus = () => {
      if (!pending) {
        return;
      }
      const element =
        pending.target === null ? grid.el : noteEls.get(String(pending.target));
      // A note not mounted yet takes the focus as it registers.
      if (element) {
        pending = null;
        element.focus({ preventScroll: true });
      }
    };

    const settings = () => {
      const wanted = options();
      const held = context.store.get();
      return {
        activePitches: wanted.activePitches,
        createNoteId: wanted.createNoteId,
        defaultSelection: wanted.defaultSelection,
        defaultValue: wanted.defaultValue,
        disabled: wanted.disabled ?? false,
        drawStyle: wanted.drawStyle,
        folded: wanted.folded ?? false,
        maxPitch: wanted.maxPitch ?? 72,
        minLength: wanted.minLength,
        minPitch: wanted.minPitch ?? 48,
        mode: wanted.mode ?? "select",
        onNoteOff: (pitch: number, details: RollNoteOffDetails) => {
          dispatch(context, "onNoteOff", pitch, {
            event: details.event,
            reason: details.reason,
          });
        },
        onNoteOn: (pitch: number, details: RollNoteOnDetails) => {
          const source = sourceOf(details.event);
          if (
            dispatch(context, "onNoteOn", pitch, {
              event: details.event,
              reason: details.reason,
              ...(source ? { source } : {}),
              velocity: details.velocity,
            })
          ) {
            details.cancel();
          }
        },
        onSelectionChange: (
          selection: readonly NoteId[],
          details: { cancel: () => void; event?: Event; reason: string }
        ) => {
          const source = sourceOf(details.event);
          if (
            !change("selection", [...selection], {
              event: details.event,
              reason: details.reason,
              ...(source ? { source } : {}),
            } as never)
          ) {
            details.cancel();
          }
        },
        onValueChange: (
          value: Note[],
          details: { cancel: () => void; event?: Event; reason: string }
        ) => {
          const { cancel, ...rest } = details;
          const source = sourceOf(details.event);
          if (
            !change("value", value, {
              ...rest,
              ...(source ? { source } : {}),
            } as never)
          ) {
            cancel();
          }
        },
        onValueCommitted: (
          value: Note[],
          details: { event?: Event; reason: string }
        ) => {
          dispatch(context, "onValueCommitted", value, { ...details });
        },
        requestFocus: (target: NoteId | null) => {
          pending = { target };
          queueMicrotask(settleFocus);
        },
        scale: wanted.scale,
        selection: held.selection,
        timeline: timelineOf({
          ...wanted,
          zoom: held.zoom,
          source: held.source,
        }),
        value: held.value,
      };
    };

    const controller: PianoRollController = createPianoRollController(
      settings() as never
    );
    const configure = () => {
      controller.setOptions(settings() as never);
      context.store.set({ view: controller.getSnapshot() } as never);
    };
    configure();
    context.onOptions(configure);
    // What the controller reads of the held state: the notes, the selection and what the timeline gave.
    const watched = () => {
      const held = context.store.get();
      return [
        held.value,
        held.selection,
        held.zoom,
        held.source,
        held.duration,
      ];
    };
    let last = watched();
    context.onDestroy(
      context.store.subscribe(() => {
        const next = watched();
        if (next.some((value, index) => value !== last[index])) {
          last = next;
          configure();
        }
      })
    );
    context.onDestroy(
      controller.subscribe(() =>
        context.store.set({ view: controller.getSnapshot() } as never)
      )
    );

    return {
      controller,
      grid,
      internal: { keyOf: (value: unknown) => String(value) },
      frozen: { ids: null as NoteId[] | null },
      noteEls,
      settleFocus,
    };
  },
  controlled: ["value", "selection"],
  name: "pianoRoll",
  options: {
    activePitches: "value",
    createNoteId: "value",
    defaultSelection: "value",
    defaultValue: "value",
    disabled: "boolean",
    drawStyle: "string",
    duration: "number",
    folded: "value",
    getNoteLabel: "value",
    maxPitch: "number",
    minLength: "number",
    minPitch: "number",
    mode: "string",
    onNoteOff: "callback",
    onNoteOn: "callback",
    onSelectionChange: "callback",
    onValueChange: "callback",
    onValueCommitted: "callback",
    position: "number",
    scale: "value",
    selection: "value",
    snapOffset: "number",
    snapPoints: "value",
    snapStep: "number",
    source: "value",
    step: "number",
    value: "value",
    zoom: "value",
  },
  slots: (slot) => {
    /** The note and the grid a gesture on a part of the note needs. */
    const noteGesture =
      (kind: "end" | "move" | "start") =>
      (
        event: PointerEvent,
        {
          api,
          el,
          props,
          store,
        }: {
          api: PianoRollApi;
          el: HTMLElement | undefined;
          props: NoteRef;
          store: { get: () => PianoRollState };
        }
      ) => {
        if (event.button !== 0) {
          return;
        }
        event.stopPropagation();
        const { grid } = api;
        if (store.get().view.disabled || !(el && grid.el)) {
          return;
        }
        event.preventDefault();
        (api.noteEls.get(String(props.note)) ?? el).focus({
          preventScroll: true,
        });
        api.controller.pressNote(
          idOf(store.get(), props.note),
          kind,
          event,
          el,
          grid.el
        );
      };

    const noteState = (
      state: PianoRollState,
      props: NoteRef
    ): NotePublicState => ({
      ...publicOf(state),
      muted: noteOf(state, props.note)?.muted ?? false,
      selected: state.view.selection.has(idOf(state, props.note)),
    });

    const edge = (kind: "end" | "start") =>
      slot({
        attrs: (state: PianoRollState, { props }: { props: NoteRef }) => ({
          ...stateAttrs(state),
          "aria-hidden": "true",
          "data-edge": kind,
          "data-muted": flag(noteOf(state, props.note)?.muted ?? false),
          "data-selected": flag(
            state.view.selection.has(idOf(state, props.note))
          ),
          style: css({ "touch-action": "none" }),
        }),
        on: { pointerdown: noteGesture(kind) },
        props: { note: "key" },
        state: (state: PianoRollState, { props }: { props: NoteRef }) => ({
          ...noteState(state, props),
          edge: kind,
        }),
      });

    const levelOf = (note: Note | undefined, level: NoteLevel) =>
      (note?.[level] as number | undefined) ?? 1;

    return {
      grid: slot({
        attrs: (state: PianoRollState) => ({
          ...stateAttrs(state),
          "data-timeline-lane": "",
          role: "group",
          style: css({ ...laneStyle(state), "touch-action": "none" }),
          tabindex: state.view.disabled ? "-1" : "0",
        }),
        bind: (el: HTMLElement, part: any) => {
          part.api.grid.el = el;
          part.api.settleFocus?.();
          return () => {
            part.api.grid.el = null;
          };
        },
        on: {
          dblclick: (
            event: MouseEvent,
            { api, el }: { api: PianoRollApi; el: HTMLElement | undefined }
          ) => {
            if (el) {
              api.controller.doubleClickGrid(event, el);
            }
          },
          keydown: (
            event: KeyboardEvent,
            {
              api,
              el,
              store,
            }: {
              api: PianoRollApi;
              el: HTMLElement | undefined;
              store: { get: () => PianoRollState };
            }
          ) => {
            if (store.get().view.disabled) {
              return;
            }
            if (api.controller.keyGrid(event)) {
              event.preventDefault();
              return;
            }
            if (event.key !== "Enter" || event.target !== el) {
              return;
            }
            event.preventDefault();
            api.controller.addAtPlayback(event);
          },
          pointerdown: (
            event: PointerEvent,
            {
              api,
              el,
              store,
            }: {
              api: PianoRollApi;
              el: HTMLElement | undefined;
              store: { get: () => PianoRollState };
            }
          ) => {
            if (!el || event.button !== 0 || store.get().view.disabled) {
              return;
            }
            event.preventDefault();
            el.focus({ preventScroll: true });
            api.controller.pressGrid(event, el);
          },
        },
        state: (state: PianoRollState) => publicOf(state),
      }),
      keys: slot({
        attrs: (state: PianoRollState) => ({
          ...stateAttrs(state),
          // A grid of one cell: the keyboard drawn inside takes the part's whole height and width.
          style: css({
            display: "grid",
            "grid-template-columns": "minmax(0, 1fr)",
            "grid-template-rows": "minmax(0, 1fr)",
          }),
        }),
        state: (state: PianoRollState, { api }: { api: PianoRollApi }) => ({
          ...publicOf(state),
          active: [...state.view.active],
          ...keyCalls(api.controller),
          pitches: state.view.rows.pitches,
        }),
      }),
      marquee: slot({
        attrs: (state: PianoRollState) => {
          const band: PianoRollBand | null = state.view.band;
          return {
            ...stateAttrs(state),
            "aria-hidden": "true",
            hidden: band === null ? "" : undefined,
            style: css({
              height: band ? `${band.height}px` : undefined,
              left: band ? `${band.left}px` : undefined,
              "pointer-events": "none",
              position: "absolute",
              top: band ? `${band.top}px` : undefined,
              width: band ? `${band.width}px` : undefined,
            }),
          };
        },
        state: (state: PianoRollState) => publicOf(state),
      }),
      note: slot({
        attrs: (state: PianoRollState, { props }: { props: NoteRef }) => {
          const note = noteOf(state, props.note);
          const selected = state.view.selection.has(idOf(state, props.note));
          return {
            ...stateAttrs(state),
            "aria-disabled": state.view.disabled ? "true" : undefined,
            "aria-label": note
              ? (state.getNoteLabel ?? describeNote)(note)
              : undefined,
            "aria-pressed": String(selected),
            "data-muted": flag(note?.muted ?? false),
            "data-note": String(props.note),
            "data-selected": flag(selected),
            hidden: note ? undefined : "",
            role: "button",
            style: css(
              note
                ? {
                    ...placedOver(note.start, note.length),
                    ...placedOnRow(state.view.rows.rowOf(note.pitch)),
                    [VELOCITY_PROPERTY]: String(note.velocity ?? 1),
                    [CHANCE_PROPERTY]: String(note.chance ?? 1),
                    "touch-action": "none",
                  }
                : {}
            ),
            tabindex: state.view.disabled ? "-1" : "0",
          };
        },
        bind: (el: HTMLElement, part: any) => {
          const id = String(part.props.note);
          part.api.noteEls.set(id, el);
          part.api.settleFocus?.();
          return () => {
            if (part.api.noteEls.get(id) === el) {
              part.api.noteEls.delete(id);
            }
          };
        },
        on: {
          blur: (event: FocusEvent, { api }: { api: PianoRollApi }) =>
            api.controller.releaseKey(event),
          dblclick: (
            event: MouseEvent,
            {
              api,
              props,
              store,
            }: {
              api: PianoRollApi;
              props: NoteRef;
              store: { get: () => PianoRollState };
            }
          ) => {
            event.stopPropagation();
            if (!store.get().view.disabled) {
              api.controller.doubleClickNote(
                idOf(store.get(), props.note),
                event
              );
            }
          },
          keydown: (
            event: KeyboardEvent,
            {
              api,
              props,
              store,
            }: {
              api: PianoRollApi;
              props: NoteRef;
              store: { get: () => PianoRollState };
            }
          ) => {
            if (store.get().view.disabled) {
              return;
            }
            if (api.controller.shortcut(event)) {
              event.preventDefault();
              // Handled: the grid around the note would run it again.
              event.stopPropagation();
              return;
            }
            if (api.controller.keyNote(idOf(store.get(), props.note), event)) {
              event.preventDefault();
            }
          },
          keyup: (event: KeyboardEvent, { api }: { api: PianoRollApi }) => {
            if (event.key === "ArrowUp" || event.key === "ArrowDown") {
              api.controller.releaseKey(event);
            }
          },
          pointerdown: noteGesture("move"),
        },
        props: { note: "key" },
        state: (state: PianoRollState, { props }: { props: NoteRef }) =>
          noteState(state, props),
      }),
      noteEnd: edge("end"),
      noteStart: edge("start"),
      // The notes in reading order: a note moved past another keeps its place in the DOM while it is dragged.
      notes: slot({
        attrs: (state: PianoRollState) => ({
          ...stateAttrs(state),
          style: css({ display: "contents" }),
        }),
        state: (state: PianoRollState, { api }: { api: PianoRollApi }) => {
          const { frozen } = api;
          let ordered = spatialOrder(state.view.notes);
          if (state.view.editing) {
            frozen.ids ??= ordered.map((note) => note.id);
            const known = new Map(
              state.view.notes.map((entry) => [entry.id, entry])
            );
            const { ids: order } = frozen;
            const kept = order.flatMap((id) => known.get(id) ?? []);
            const added = ordered.filter((entry) => !order.includes(entry.id));
            ordered = [...kept, ...added];
          } else {
            frozen.ids = null;
          }
          return { ...publicOf(state), notes: ordered };
        },
      }),
      root: slot({
        attrs: (state: PianoRollState) => ({
          ...stateAttrs(state),
          "data-has-selection": flag(state.view.selection.size > 0),
          style: css({
            [ROWS_PROPERTY]: String(state.view.rows.pitches.length),
          }),
        }),
        state: (state: PianoRollState) => publicOf(state),
      }),
      row: slot({
        attrs: (
          state: PianoRollState,
          { props }: { props: PartProps & { pitch: number } }
        ) => {
          const view = rowState(state, Number(props.pitch));
          return {
            ...stateAttrs(state),
            "aria-hidden": "true",
            "data-active": flag(view.active),
            "data-color": view.color,
            "data-in-scale": flag(view.inScale),
            "data-octave": flag(view.octave),
            "data-out-of-scale": flag(view.outOfScale),
            "data-pitch": String(props.pitch),
            "data-scale-root": flag(view.scaleRoot),
            style: css({
              ...placedOnRow(state.view.rows.rowOf(Number(props.pitch))),
              left: "0",
              "pointer-events": "none",
              right: "0",
            }),
          };
        },
        props: { pitch: "key" },
        state: (
          state: PianoRollState,
          { props }: { props: PartProps & { pitch: number } }
        ) => rowState(state, Number(props.pitch)),
      }),
      rows: slot({
        attrs: (state: PianoRollState) => ({
          ...stateAttrs(state),
          style: css({ display: "contents" }),
        }),
        state: (state: PianoRollState) => ({
          ...publicOf(state),
          pitches: state.view.rows.pitches,
        }),
      }),
      selectionSpan: slot({
        attrs: (state: PianoRollState) => {
          const span = selectionSpan(state.view.notes, state.view.selection);
          return {
            ...stateAttrs(state),
            "aria-hidden": "true",
            hidden: span === null ? "" : undefined,
            style: css({
              ...(span ? placedOver(span.start, span.end - span.start) : {}),
              bottom: "0",
              "pointer-events": "none",
              position: "absolute",
              top: "0",
            }),
          };
        },
        state: (state: PianoRollState) => publicOf(state),
      }),
      stretchEnd: stretch("end", slot),
      stretchStart: stretch("start", slot),
      velocity: slot({
        attrs: (state: PianoRollState, { props }: { props: VelocityProps }) => {
          const note = noteOf(state, props.note);
          const level = props.level ?? "velocity";
          const value = levelOf(note, level);
          return {
            ...stateAttrs(state),
            "data-muted": flag(note?.muted ?? false),
            "data-note": String(props.note),
            "data-selected": flag(
              state.view.selection.has(idOf(state, props.note))
            ),
            hidden: note ? undefined : "",
            style: css(
              note
                ? {
                    ...placedAt(note.start),
                    [LEVEL_PROPERTY]: String(value),
                    [VELOCITY_PROPERTY]: String(note.velocity ?? 1),
                    [CHANCE_PROPERTY]: String(note.chance ?? 1),
                    [DEVIATION_PROPERTY]: String(note.deviation ?? 0),
                    bottom: "0",
                    height: `calc(var(${LEVEL_PROPERTY}) * 100%)`,
                    "touch-action": "none",
                  }
                : {}
            ),
          };
        },
        on: {
          pointerdown: (
            event: PointerEvent,
            {
              api,
              el,
              props,
              store,
            }: {
              api: PianoRollApi;
              el: HTMLElement | undefined;
              props: VelocityProps;
              store: { get: () => PianoRollState };
            }
          ) => {
            if (!el || event.button !== 0 || store.get().view.disabled) {
              return;
            }
            event.preventDefault();
            el.querySelector<HTMLInputElement>('input[type="range"]')?.focus({
              preventScroll: true,
            });
            api.controller.pressVelocity(
              idOf(store.get(), props.note),
              event,
              el,
              el.closest<HTMLElement>("[data-timeline-lane]"),
              props.level ?? "velocity"
            );
          },
        },
        props: { getAriaValueText: "value", level: "string", note: "key" },
        state: (
          state: PianoRollState,
          { props }: { props: VelocityProps }
        ) => ({
          ...publicOf(state),
          muted: noteOf(state, props.note)?.muted ?? false,
          selected: state.view.selection.has(idOf(state, props.note)),
        }),
      }),
      velocityInput: slot({
        attrs: (state: PianoRollState, { props }: { props: VelocityProps }) => {
          const note = noteOf(state, props.note);
          const value = levelOf(note, props.level ?? "velocity");
          return {
            "aria-valuetext": (props.getAriaValueText ?? describeVelocity)(
              value
            ),
            disabled: flag(state.view.disabled),
            max: "1",
            min: "0",
            step: "any",
            style: css(VISUALLY_HIDDEN),
            type: "range",
            value: String(value),
          };
        },
        on: {
          change: (
            event: Event,
            {
              api,
              el,
              props,
              store,
            }: {
              api: PianoRollApi;
              el: HTMLElement | undefined;
              props: VelocityProps;
              store: { get: () => PianoRollState };
            }
          ) =>
            api.controller.setVelocity(
              idOf(store.get(), props.note),
              Number((el as HTMLInputElement).value),
              event,
              props.level ?? "velocity"
            ),
          keydown: (
            event: KeyboardEvent,
            {
              api,
              props,
              store,
            }: {
              api: PianoRollApi;
              props: VelocityProps;
              store: { get: () => PianoRollState };
            }
          ) => {
            if (store.get().view.disabled) {
              return;
            }
            if (
              api.controller.keyVelocity(
                idOf(store.get(), props.note),
                event,
                props.level ?? "velocity"
              )
            ) {
              event.preventDefault();
            }
          },
        },
        props: { getAriaValueText: "value", level: "string", note: "key" },
      }),
      // A lane for the notes' velocities, or their chances: a press between the bars paints in draw mode.
      velocityLane: slot({
        attrs: (
          state: PianoRollState,
          { props }: { props: VelocityLaneProps }
        ) => ({
          ...stateAttrs(state),
          "data-level": props.level ?? "velocity",
          "data-timeline-lane": "",
          role: "group",
          style: css(laneStyle(state)),
        }),
        on: {
          // A bar takes its own presses; one on the lane between them paints.
          pointerdown: (
            event: PointerEvent,
            {
              api,
              el,
              props,
            }: {
              api: PianoRollApi;
              el: HTMLElement | undefined;
              props: VelocityLaneProps;
            }
          ) => {
            if (el && !event.defaultPrevented) {
              api.controller.paintLevels(event, el, props.level ?? "velocity");
            }
          },
        },
        props: { level: "string" },
        state: (
          state: PianoRollState,
          { props }: { props: VelocityLaneProps }
        ) => ({ ...publicOf(state), level: props.level ?? "velocity" }),
      }),
    };
  },
  state: (options: PianoRollPrimitiveOptions): PianoRollState => {
    const notes = options.value ?? options.defaultValue ?? [];
    const selection = options.selection ?? options.defaultSelection ?? [];
    const zoom = options.zoom ?? null;
    const view = createPianoRollController({
      defaultValue: options.defaultValue,
      disabled: options.disabled ?? false,
      folded: options.folded ?? false,
      maxPitch: options.maxPitch ?? 72,
      minPitch: options.minPitch ?? 48,
      mode: options.mode ?? "select",
      scale: options.scale,
      selection,
      timeline: timelineOf(options),
      value: notes,
    } as never).getSnapshot();
    return {
      duration: options.duration ?? 1,
      getNoteLabel: options.getNoteLabel,
      selection,
      source: options.source,
      value: notes,
      view,
      zoom,
    };
  },
  sync: (options: PianoRollPrimitiveOptions) => ({
    duration: options.duration ?? 1,
    getNoteLabel: options.getNoteLabel,
    ...(options.value === undefined ? {} : { value: options.value }),
    ...(options.selection === undefined
      ? {}
      : { selection: options.selection }),
    source: options.source,
    zoom: options.zoom ?? null,
  }),
});

/** What a row reads: whether it sounds, its colour and its place in the scale. */
function rowState(state: PianoRollState, pitch: number): RowPublicState {
  const { rows, active } = state.view;
  const pitchClass = ((pitch % 12) + 12) % 12;
  const inScale = rows.scale?.includes(pitchClass) ?? false;
  return {
    ...publicOf(state),
    active: active.has(pitch),
    color: isBlackKey(pitch) ? "black" : "white",
    inScale,
    octave: pitchClass === 0,
    outOfScale: rows.scale !== null && !inScale,
    scaleRoot: (rows as Rows).root === pitchClass,
  };
}

/** A handle on the selection's span that stretches the selected notes from one edge. */
function stretch(kind: "end" | "start", slot: any) {
  return slot({
    attrs: (state: PianoRollState) => ({
      ...stateAttrs(state),
      "aria-hidden": "true",
      "data-edge": kind,
      style: css({
        [kind === "start" ? "left" : "right"]: "0",
        bottom: "0",
        "pointer-events": "auto",
        position: "absolute",
        top: "0",
        "touch-action": "none",
      }),
    }),
    on: {
      pointerdown: (
        event: PointerEvent,
        { api, el }: { api: PianoRollApi; el: HTMLElement | undefined }
      ) => {
        if (api.grid.el && el) {
          event.stopPropagation();
          api.controller.pressStretch(kind, event, el, api.grid.el);
        }
      },
    },
    state: (state: PianoRollState) => ({ ...publicOf(state), edge: kind }),
  });
}

/** The note names of a pitch class, from C. */
const NAMES = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
const BLACK = new Set([1, 3, 6, 8, 10]);

/** The pitch class of `pitch`, 0 for C to 11 for B. */
const classOf = (pitch: number) => ((Math.round(pitch) % 12) + 12) % 12;

/** "C", "C#", "D"... for the note nearest `pitch`, without its octave. */
export function pitchClassName(pitch: number) {
  return NAMES[classOf(pitch)] ?? "";
}

/** "C4" for middle C (MIDI 60), the naming tuners and score editors agree on. */
export function pitchName(pitch: number) {
  const rounded = Math.round(pitch);
  return `${pitchClassName(rounded)}${Math.floor(rounded / 12) - 1}`;
}

/** Whether `pitch` falls on a black key of a piano. */
export const isBlackKey = (pitch: number) => BLACK.has(classOf(pitch));

/**
 * The grid the timeline and the piano roll snap to, and the ranges they move:
 * shared by both, beside `primitive.ts`.
 */

import { clamp } from "@ui-sdk/core/number";

/** `value` within `min` and `max`, or `min` when it is not a number. */
export const clampFinite = (value: number, min: number, max: number) =>
  Number.isFinite(value) ? clamp(value, min, max) : min;

/** A stretch of a timeline, `[start, end]` in its units. */
export type RangeValue = readonly [start: number, end: number];

/** What a change moves: one edge, or the whole range with `both`. */
export type RangeEdge = "both" | "end" | "start";

/** What a range is kept within: the timeline's length and the shortest it may be. */
export interface RangeLimits {
  duration: number;
  /** The shortest a range may be resized to. */
  minLength: number;
}

/** Orders a range's edges and keeps them on the timeline. */
export function normalizeRange(
  value: RangeValue,
  duration: number
): RangeValue {
  const first = clampFinite(value[0], 0, duration);
  const second = clampFinite(value[1], 0, duration);
  return first <= second ? [first, second] : [second, first];
}

/**
 * Moves one edge of `origin` by `delta`, or the whole range, without leaving
 * the timeline. An edge stops `minLength` short of the other one; a range
 * moved as a whole keeps its length.
 */
export function moveRange(
  origin: RangeValue,
  edge: RangeEdge,
  delta: number,
  limits: RangeLimits
): RangeValue {
  const [start, end] = origin;
  const { duration, minLength } = limits;
  if (edge === "both") {
    const length = end - start;
    const next = clamp(start + delta, 0, Math.max(0, duration - length));
    return [next, next + length];
  }
  if (edge === "start") {
    return [clamp(start + delta, 0, Math.max(0, end - minLength)), end];
  }
  return [
    start,
    clamp(end + delta, Math.min(duration, start + minLength), duration),
  ];
}

/**
 * Grid lines `step` apart, starting from `offset`. A `step` of 0 or less is no
 * grid. `points` are places that pull harder than the lines, such as the
 * edges of other clips and the locators: within `radius` of one, a dragged
 * thing lands on it. The radius is set per gesture from how many units a few
 * pixels are.
 */
export interface Grid {
  offset: number;
  points?: readonly number[];
  radius?: number;
  step: number;
}

/** How far from a snap point, in px, a dragged thing is pulled onto it. */
export const SNAP_RADIUS_PX = 8;

/** The grid with its points pulling from `radius` units away, so a gesture can set it from its own zoom. */
export function withSnapRadius(grid: Grid, radius: number): Grid {
  return grid.points?.length ? { ...grid, radius } : grid;
}

/** The point of `grid` nearest `value` within its radius, or null when none is that close. */
export function nearestSnapPoint(value: number, grid: Grid): number | null {
  const radius = grid.radius ?? 0;
  let found: number | null = null;
  for (const point of grid.points ?? []) {
    const distance = Math.abs(point - value);
    if (
      distance <= radius &&
      (found === null || distance < Math.abs(found - value))
    ) {
      found = point;
    }
  }
  return found;
}

/** Whether a gesture asks to ignore the grid: Cmd on a Mac, Ctrl elsewhere. */
export function bypassesGrid(event: {
  ctrlKey?: boolean;
  metaKey?: boolean;
}): boolean {
  return Boolean(event.metaKey || event.ctrlKey);
}

/** The snap point within reach of `value`, or else the grid line nearest it. */
export function snapToGrid(value: number, grid: Grid): number {
  const point = nearestSnapPoint(value, grid);
  if (point !== null) {
    return point;
  }
  if (!(grid.step > 0)) {
    return value;
  }
  return (
    Math.round((value - grid.offset) / grid.step) * grid.step + grid.offset
  );
}

/**
 * Where something dragged from `origin` should land, given where the pointer
 * would put it. A snap point within reach wins. Otherwise two answers are
 * reasonable, and the one nearer the pointer wins: on a grid line, or moved
 * by a whole number of steps from where it was. Without the second, anything that starts between two lines jumps onto
 * one the moment it is touched, and can never move by exactly one step.
 */
export function snapMove(target: number, origin: number, grid: Grid): number {
  const point = nearestSnapPoint(target, grid);
  if (point !== null) {
    return point;
  }
  if (!(grid.step > 0)) {
    return target;
  }
  const onLine = snapToGrid(target, grid);
  const bySteps =
    origin + Math.round((target - origin) / grid.step) * grid.step;
  return Math.abs(onLine - target) <= Math.abs(bySteps - target)
    ? onLine
    : bySteps;
}

/**
 * Where a span `length` long, dragged from `origin`, should start when the
 * pointer would start it at `target`: either of its edges lands on a snap
 * point within reach (the nearer one wins), or else its start snaps the way
 * anything dragged does.
 */
export function snapSpanMove(
  target: number,
  origin: number,
  length: number,
  grid: Grid
): number {
  const startPoint = nearestSnapPoint(target, grid);
  const endPoint = nearestSnapPoint(target + length, grid);
  if (startPoint !== null || endPoint !== null) {
    if (endPoint === null) {
      return startPoint ?? target;
    }
    if (
      startPoint === null ||
      Math.abs(endPoint - (target + length)) < Math.abs(startPoint - target)
    ) {
      return endPoint - length;
    }
    return startPoint;
  }
  return snapMove(target, origin, { ...grid, points: undefined });
}

/** The grid without the given points, so something dragged is not pulled onto its own edges. */
export function withoutSnapPoints(grid: Grid, own: readonly number[]): Grid {
  return grid.points?.length
    ? { ...grid, points: grid.points.filter((point) => !own.includes(point)) }
    : grid;
}

/**
 * Where one edge of a range dragged from `origin`, or the whole range with
 * `"both"`, should land when the pointer has moved it by `delta`: the
 * dragged edge snaps the way anything dragged does, and the range keeps
 * within the timeline and its minimum length.
 */
export function snapRangeMove(
  origin: RangeValue,
  edge: RangeEdge,
  delta: number,
  limits: RangeLimits,
  grid: Grid
): RangeValue {
  if (edge === "both") {
    const length = origin[1] - origin[0];
    return moveRange(
      origin,
      edge,
      snapSpanMove(origin[0] + delta, origin[0], length, grid) - origin[0],
      limits
    );
  }
  const from = edge === "end" ? origin[1] : origin[0];
  return moveRange(
    origin,
    edge,
    snapMove(from + delta, from, grid) - from,
    limits
  );
}

import { clamp } from "@ui-sdk/core/number";
import { bypassesGrid, type Grid, snapMove, snapToGrid } from "../grid";
import {
  type ChangeEventDetails,
  type CommitEventDetails,
  createChangeEventDetails,
  createPointerLock,
} from "../primitive";
import {
  cellStart,
  changeLevel,
  duplicateAfter,
  duplicateNotes,
  keyboardEdit,
  moveNotes,
  type Note,
  type NoteId,
  type NoteLevel,
  notesWithin,
  pasteNotes,
  quantizeNotes,
  type RollBounds,
  resizeNotes,
  sameNotes,
  sanitizeNote,
  selectionSpan,
  setDeviation,
  snapEdgeDelta,
  spatialOrder,
  stretchNotes,
} from "./edits";
import { type RollScale, type Rows, rollRows } from "./rows";

/** A gesture between two frames is followed in steps this long, in px, so a quick stroke misses no cell. */
const STROKE_SAMPLE_PX = 4;

/** The points of a stroke from `from` to `to`, at most `spacing` px apart, so it touches every cell it crosses. */
function strokePoints(
  from: { x: number; y: number },
  x: number,
  y: number,
  spacing: number
) {
  const count = Math.max(
    1,
    Math.ceil(Math.hypot(x - from.x, y - from.y) / Math.max(spacing, 0.5))
  );
  return Array.from({ length: count }, (_, index) => {
    const t = (index + 1) / count;
    return { x: from.x + (x - from.x) * t, y: from.y + (y - from.y) * t };
  });
}

/** How far a pointer moves before a press on the grid or a note becomes a drag. */
export const DRAG_THRESHOLD = 4;
/** What the arrow keys change a velocity by; Page Up/Down move five times as far. */
const VELOCITY_STEP = 0.05;
const VELOCITY_LARGE_STEP = 0.25;
const EMPTY_NOTES: readonly Note[] = [];
const EMPTY_IDS: readonly NoteId[] = [];
const NO_GRID: Grid = { offset: 0, step: 0 };

/** What a change did to the notes. */
export type PianoRollEdit =
  | "add"
  | "chance"
  | "deviation"
  | "duplicate"
  | "move"
  | "paste"
  | "quantize"
  | "remove"
  | "resize"
  | "stretch"
  | "velocity";

type Edited<Details> = Details & {
  /** A gesture reuses one `edit` for all of its changes. */
  edit: PianoRollEdit;
};

/** What `onValueChange` receives with each change: the `edit` it made (one for every change of a gesture), the reason, the event behind it, and `cancel()` to refuse the change. */
export type PianoRollChangeEventDetails =
  | Edited<ChangeEventDetails<"draw" | "drag", PointerEvent>>
  | Edited<ChangeEventDetails<"keyboard", KeyboardEvent>>
  | Edited<ChangeEventDetails<"double-click", MouseEvent>>
  | Edited<ChangeEventDetails<"input-change", Event>>;
/** Why the notes changed: `"draw"`, `"drag"`, `"keyboard"`, `"double-click"` or `"input-change"`. */
export type PianoRollChangeEventReason = PianoRollChangeEventDetails["reason"];
/** What `onValueCommitted` receives once a gesture ends: the `edit` it made (one for every change of a gesture), the reason and the event behind it. */
export type PianoRollCommitEventDetails =
  | Edited<CommitEventDetails<"draw" | "drag", PointerEvent>>
  | Edited<CommitEventDetails<"keyboard", KeyboardEvent>>
  | Edited<CommitEventDetails<"double-click", MouseEvent>>
  | Edited<CommitEventDetails<"input-change", Event>>;
/** Why the notes were committed: the same reasons as a change. */
export type PianoRollCommitEventReason = PianoRollCommitEventDetails["reason"];

/** What `onSelectionChange` receives: the reason (`"press"`, `"marquee"`, `"draw"`, `"drag"`, `"keyboard"` or `"double-click"`), the event, and `cancel()` to refuse it. */
export type PianoRollSelectionEventDetails =
  | ChangeEventDetails<"press" | "marquee" | "draw" | "drag", PointerEvent>
  | ChangeEventDetails<"keyboard", KeyboardEvent>
  | ChangeEventDetails<"double-click", MouseEvent>;

type WithVelocity<Details> = Details & {
  /** How hard the note is played, 0…1. */
  velocity: number;
};

/** Why a pitch sounds: a key pressed, glided onto or played from the keyboard, or a note drawn, picked up or moved. */
export type PianoRollNoteOnEventDetails =
  | WithVelocity<ChangeEventDetails<"press" | "glide", PointerEvent>>
  | WithVelocity<ChangeEventDetails<"keyboard", KeyboardEvent>>
  | WithVelocity<ChangeEventDetails<"draw" | "drag", PointerEvent>>;

/** What `onNoteOff` receives when a pitch stops: the reason and the event. */
export type PianoRollNoteOffEventDetails =
  | CommitEventDetails<"press" | "glide" | "draw" | "drag", PointerEvent>
  | CommitEventDetails<"keyboard", FocusEvent | KeyboardEvent>;

/** A key pressed on the keyboard beside the roll, before it sounds. */
export type PianoRollKeyDetails =
  | ChangeEventDetails<"press" | "glide", PointerEvent>
  | ChangeEventDetails<"keyboard", KeyboardEvent>;

/** A selection rectangle, in px from the grid's top left corner. */
export interface PianoRollBand {
  height: number;
  left: number;
  top: number;
  width: number;
}

/** The timeline the roll sits in: its length, grid, zoom and playback position. */
export interface PianoRollTimeline {
  duration: number;
  grid: Grid;
  /** The playback position, in the timeline's units. */
  position: () => number;
  step: number;
  /** Pixels per unit, or null when the timeline fits its lane. */
  zoom: number | null;
}

/** The options of `createPianoRollController`: the notes and the selection, each held or controlled, the timeline, the pitch range and shortest note, the mode, the draw style, the scale and folding, and the callbacks. */
export interface PianoRollOptions {
  activePitches?: readonly number[];
  /** Returns the id of a note drawn, added or duplicated. Defaults to `"note-<n>"`, skipping ids in use. */
  createNoteId?: () => NoteId;
  defaultSelection?: readonly NoteId[];
  defaultValue?: readonly Note[];
  disabled?: boolean;
  /**
   * What a drag does after a press on the grid in draw mode: stretch the note
   * drawn, or paint a note in each grid cell the pointer crosses, on the
   * pitch under it, or with Alt on the first one. @default "stretch"
   */
  drawStyle?: "paint" | "stretch";
  /** Whether only the pitches carrying notes get a row, and with `"scale"` those in `scale` too. @default false */
  folded?: boolean | "scale";
  /** @default 72 */
  maxPitch?: number;
  /** The shortest a note can be, in the timeline's units. Defaults to the timeline's grid step. */
  minLength?: number;
  /** @default 48 */
  minPitch?: number;
  /** What a press on empty grid does: draw a note, or start a selection rectangle. @default "select" */
  mode?: "draw" | "select";
  onNoteOff?: (pitch: number, details: PianoRollNoteOffEventDetails) => void;
  onNoteOn?: (pitch: number, details: PianoRollNoteOnEventDetails) => void;
  onSelectionChange?: (
    selection: readonly NoteId[],
    details: PianoRollSelectionEventDetails
  ) => void;
  onValueChange?: (value: Note[], details: PianoRollChangeEventDetails) => void;
  onValueCommitted?: (
    value: Note[],
    details: PianoRollCommitEventDetails
  ) => void;
  /** Asks the view to move focus to a note, or to the grid with `null`, once it has rendered. */
  requestFocus?: (target: NoteId | null) => void;
  /** The scale whose rows are marked, and which `folded: "scale"` keeps. */
  scale?: RollScale | null;
  selection?: readonly NoteId[];
  timeline: PianoRollTimeline;
  value?: readonly Note[];
}

/** What a view draws the roll from. */
export interface PianoRollSnapshot {
  /** Pitches sounding: auditioned here, or listed in `activePitches`. */
  active: ReadonlySet<number>;
  band: PianoRollBand | null;
  bounds: RollBounds;
  disabled: boolean;
  /** Whether a pointer is drawing, moving, resizing or selecting notes. */
  editing: boolean;
  folded: boolean;
  mode: "draw" | "select";
  noteById: ReadonlyMap<NoteId, Note>;
  /** The notes as displayed. */
  notes: readonly Note[];
  rows: Rows;
  selection: ReadonlySet<NoteId>;
}

/** Which pointer handle a note gesture takes: its body, or one of its edges. */
export type PianoRollNoteHandle = "end" | "move" | "start";

/** What `createPianoRollController` returns: the snapshot to draw from, and a call for each gesture, key and command that edits the notes or the selection. */
export interface PianoRollController {
  /** Adds a note at the playback position, from the keyboard. Returns `true` when the note is added. */
  addAtPlayback: (event: KeyboardEvent) => boolean;
  doubleClickGrid: (event: MouseEvent, grid: Element) => void;
  doubleClickNote: (id: NoteId, event: MouseEvent) => void;
  getSnapshot: () => PianoRollSnapshot;
  /** Handles a key on the grid: a command, Escape clears the selection, Cmd/Ctrl+A selects all. Returns `true` when the grid takes the key. */
  keyGrid: (event: KeyboardEvent) => boolean;
  /** Handles a key on a note: Delete removes, Enter and Space toggle its selection, arrows move it, Shift + arrows resize it. Returns `true` when the note takes the key. */
  keyNote: (id: NoteId, event: KeyboardEvent) => boolean;
  keyOff: (pitch: number, details: PianoRollNoteOffEventDetails) => void;
  /** A key on the keyboard beside the roll: sounds it, or with Shift selects the notes on its row. */
  keyOn: (pitch: number, details: PianoRollKeyDetails) => void;
  /** Handles a key on a velocity's input, or a chance's with `level` "chance". Returns `true` when it takes the key. */
  keyVelocity: (id: NoteId, event: KeyboardEvent, level?: NoteLevel) => boolean;
  /**
   * Starts a press on a velocity or chance lane in draw mode: a drag paints
   * every bar under the pointer, in the grid cell it is over, to the
   * pointer's height. Does nothing in select mode.
   */
  paintLevels: (event: PointerEvent, lane: Element, level?: NoteLevel) => void;
  /** Starts a press on the grid: a draw in draw mode, or a selection rectangle. */
  pressGrid: (event: PointerEvent, grid: Element) => void;
  /** Starts a press on a note: a drag moves it, or resizes it from an edge; Alt copies, Shift toggles its selection. */
  pressNote: (
    id: NoteId,
    handle: PianoRollNoteHandle,
    event: PointerEvent,
    element: Element,
    grid: Element
  ) => void;
  /** Starts a press on one edge of the selection's span: a drag stretches the selected notes in time from the other edge. */
  pressStretch: (
    edge: "end" | "start",
    event: PointerEvent,
    element: Element,
    grid: Element
  ) => void;
  /**
   * Starts a press on a velocity bar, or a chance bar with `level` "chance": a
   * drag changes the selection's, or the note's. On a velocity bar with
   * Cmd/Ctrl, the drag sets how far the velocity may stray instead.
   */
  pressVelocity: (
    id: NoteId,
    event: PointerEvent,
    element: Element,
    lane: Element | null,
    level?: NoteLevel
  ) => void;
  /** Stops the pitch a key moved a note to, once the key is released. */
  releaseKey: (event: Event) => void;
  setOptions: (options: PianoRollOptions) => void;
  /** Sets a velocity, or a chance with `level` "chance", from an input, reporting an `"input-change"` change and commit. */
  setVelocity: (
    id: NoteId,
    value: number,
    event: Event,
    level?: NoteLevel
  ) => void;
  /** Handles a Cmd/Ctrl command: copy, cut, paste, duplicate, quantize. Returns `true` when the key is one of them. */
  shortcut: (event: KeyboardEvent) => boolean;
  subscribe: (listener: () => void) => () => void;
}

/** One pointer gesture on a note, from press to release. */
interface NoteGesture {
  anchor: Note;
  changed: boolean;
  /** Alt was held: the drag carries copies off and leaves the notes. */
  copy: boolean;
  edit: PianoRollEdit;
  grid: Element;
  handle: PianoRollNoteHandle;
  /** The notes the gesture moves: the selection, or just this note. */
  ids: ReadonlySet<NoteId>;
  /** The notes when the gesture began: every move is measured from them. */
  origin: Note[];
  rowHeight: number;
  /** The rows when the gesture began, which a folded roll changes under it. */
  rows: Rows;
  sounding: number | null;
  started: boolean;
  startX: number;
  startY: number;
}

/** One pointer gesture on the grid: a note drawn to its end, or a selection rectangle. */
type GridGesture =
  | {
      grid: Element;
      id: NoteId;
      kind: "draw";
      sounding: number | null;
      start: number;
      started: boolean;
      startX: number;
      startY: number;
    }
  | {
      /** The cells painted, by their start, so a cell is painted once. */
      cells: Set<number>;
      grid: Element;
      /** The notes painted, kept selected together. */
      ids: NoteId[];
      kind: "paint";
      /** The pitch of the first note: Alt keeps the next ones on it. */
      pitch: number;
      sounding: number | null;
    }
  | {
      /** What was selected before, kept when Shift started the rectangle. */
      base: readonly NoteId[];
      grid: Element;
      kind: "marquee";
      x: number;
      y: number;
    };

interface VelocityGesture {
  changed: boolean;
  /** Cmd/Ctrl was held on a velocity bar: the drag sets the deviation. */
  deviation: boolean;
  /** The lane's height: a drag across all of it goes from silent to full. */
  height: number;
  id: NoteId;
  ids: ReadonlySet<NoteId>;
  level: NoteLevel;
  origin: Note[];
  startY: number;
}

/** One drag across a lane in draw mode, painting the bars under the pointer. */
interface PaintLevelGesture {
  changed: boolean;
  lane: Element;
  level: NoteLevel;
}

/** One drag of an edge of the selection's span, stretching it from the other. */
interface StretchGesture {
  /** The edge that stays put. */
  anchor: number;
  changed: boolean;
  edge: "end" | "start";
  grid: Element;
  ids: ReadonlySet<NoteId>;
  /** Where the dragged edge was. */
  moving: number;
  origin: Note[];
}

/** The timeline's units under a point of `element`, clamped to the timeline. */
function timeAt(
  element: Element,
  clientX: number,
  zoom: number | null,
  duration: number
): number {
  const rect = element.getBoundingClientRect();
  const unit = zoom ?? rect.width / Math.max(duration, Number.MIN_VALUE);
  const value = (clientX - rect.left) / Math.max(unit, Number.MIN_VALUE);
  return Math.min(duration, Math.max(0, value));
}

/** Where a gesture puts the notes once the pointer has moved by `units` across and `dy` px down. */
function draggedNotes(
  gesture: NoteGesture,
  units: number,
  dy: number,
  grid: Grid,
  bounds: RollBounds
): Note[] {
  const { anchor, handle } = gesture;
  if (handle !== "move") {
    return resizeNotes(
      gesture.origin,
      gesture.ids,
      handle,
      snapEdgeDelta(anchor, handle, units, grid),
      bounds
    );
  }
  const start = snapMove(anchor.start + units, anchor.start, grid);
  const rows = gesture.rowHeight > 0 ? Math.round(dy / gesture.rowHeight) : 0;
  return moveNotes(
    gesture.origin,
    gesture.ids,
    start - anchor.start,
    gesture.rows.step(anchor.pitch, rows) - anchor.pitch,
    bounds
  );
}

/** What a drag on a lane's bar edits: the velocity, its deviation, or the chance. */
function velocityEdit(gesture: VelocityGesture): PianoRollEdit {
  return gesture.deviation ? "deviation" : gesture.level;
}

/**
 * A piano roll's behavior with no view attached: its notes, held or
 * controlled, its selection and the pitches sounding, and every gesture and
 * key that edits them.
 */
export function createPianoRollController(
  initial: PianoRollOptions
): PianoRollController {
  let options = initial;
  const pointers = createPointerLock();
  const bounds = (): RollBounds => {
    const { duration, grid, step } = options.timeline;
    return {
      duration,
      maxPitch: options.maxPitch ?? 72,
      minLength: options.minLength ?? (grid.step > 0 ? grid.step : step),
      minPitch: options.minPitch ?? 48,
    };
  };

  // Notes: held by the roll, unless `value` is given.
  let uncontrolled: readonly Note[] | undefined;
  // Holds the notes a gesture edits until it ends, so a controlled value that
  // lags behind can't pull them back mid-gesture.
  let dragValue: Note[] | null = null;
  let editing = false;
  let sanitizedKey = "";
  let sanitized = new WeakMap<Note, Note>();
  let heldFor: readonly Note[] | null = null;
  let heldValue: readonly Note[] = EMPTY_NOTES;

  // Selection: held by the roll, unless `selection` is given.
  let uncontrolledSelection: readonly NoteId[] | undefined;
  let selectionFor: readonly NoteId[] | null = null;
  let selectionSet: ReadonlySet<NoteId> = new Set();

  // Pitches sounding, and the one a key moved a note to.
  let sounding = new Set<number>();
  let keySounding: number | null = null;
  let band: PianoRollBand | null = null;
  let noteGesture: NoteGesture | null = null;
  let gridGesture: GridGesture | null = null;
  let velocityGesture: VelocityGesture | null = null;
  let stretchGesture: StretchGesture | null = null;
  let paintLevelGesture: PaintLevelGesture | null = null;
  // The length and velocity a drawn note gets: those last drawn or resized.
  let drawTemplate: { length: number; velocity: number } | null = null;
  let lastPitch: number | null = null;
  let clipboard: readonly Note[] = [];
  let nextId = 0;

  const listeners = new Set<() => void>();
  const notify = () => {
    for (const listener of listeners) {
      listener();
    }
  };

  const displayed = (): readonly Note[] => {
    if (dragValue) {
      return dragValue;
    }
    const held =
      options.value ?? uncontrolled ?? options.defaultValue ?? EMPTY_NOTES;
    const key = JSON.stringify(bounds());
    if (held === heldFor && key === sanitizedKey) {
      return heldValue;
    }
    if (key !== sanitizedKey) {
      sanitized = new WeakMap<Note, Note>();
      sanitizedKey = key;
    }
    const limits = bounds();
    heldValue = held.map((note) => {
      const known = sanitized.get(note);
      if (known) {
        return known;
      }
      const next = sanitizeNote(note, limits);
      sanitized.set(note, next);
      return next;
    });
    heldFor = held;
    return heldValue;
  };

  const selectedIds = (): ReadonlySet<NoteId> => {
    const list =
      options.selection ??
      uncontrolledSelection ??
      options.defaultSelection ??
      EMPTY_IDS;
    if (list !== selectionFor) {
      selectionFor = list;
      selectionSet = new Set(list);
    }
    return selectionSet;
  };

  let rowsKey = "";
  let rowsCache: Rows | null = null;
  const rowsFor = (notes: readonly Note[]): Rows => {
    const folded = options.folded ?? false;
    const min = options.minPitch ?? 48;
    const max = options.maxPitch ?? 72;
    // Only folded rows depend on which pitches carry notes.
    const pitchKey = folded
      ? [...new Set(notes.map((note) => note.pitch))]
          .sort((a, b) => a - b)
          .join(",")
      : "";
    const scale = options.scale ?? null;
    const key = `${folded}|${min}|${max}|${pitchKey}|${scale?.root}|${scale?.pitchClasses.join(",")}`;
    if (!rowsCache || key !== rowsKey) {
      rowsKey = key;
      rowsCache = rollRows(notes, min, max, folded, scale);
    }
    return rowsCache;
  };

  let noteMapFor: readonly Note[] | null = null;
  let noteMap: ReadonlyMap<NoteId, Note> = new Map();
  const noteById = (notes: readonly Note[]) => {
    if (notes !== noteMapFor) {
      noteMapFor = notes;
      noteMap = new Map(notes.map((note) => [note.id, note]));
    }
    return noteMap;
  };

  const activeSet = (): ReadonlySet<number> =>
    new Set([...sounding, ...(options.activePitches ?? [])]);

  let snapshot: PianoRollSnapshot | null = null;
  const getSnapshot = (): PianoRollSnapshot => {
    const notes = displayed();
    const selection = selectedIds();
    const active = activeSet();
    const limits = bounds();
    const rows = rowsFor(notes);
    const disabled = options.disabled ?? false;
    const mode = options.mode ?? "select";
    if (
      snapshot &&
      snapshot.notes === notes &&
      snapshot.selection === selection &&
      snapshot.rows === rows &&
      snapshot.band === band &&
      snapshot.editing === editing &&
      snapshot.disabled === disabled &&
      snapshot.mode === mode &&
      snapshot.bounds.duration === limits.duration &&
      snapshot.bounds.minLength === limits.minLength &&
      snapshot.bounds.minPitch === limits.minPitch &&
      snapshot.bounds.maxPitch === limits.maxPitch &&
      snapshot.active.size === active.size &&
      [...active].every((pitch) => snapshot?.active.has(pitch))
    ) {
      return snapshot;
    }
    snapshot = {
      active,
      band,
      bounds: limits,
      disabled,
      editing,
      folded: rows.folded,
      mode,
      noteById: noteById(notes),
      notes,
      rows,
      selection,
    };
    return snapshot;
  };

  /** Proposes new notes: reports them, and keeps them unless canceled. */
  const change = (next: Note[], details: PianoRollChangeEventDetails) => {
    if (sameNotes(next, displayed())) {
      return false;
    }
    options.onValueChange?.(next, details);
    if (details.isCanceled) {
      return false;
    }
    if (options.value === undefined) {
      uncontrolled = next;
    } else if (editing) {
      dragValue = next;
    }
    notify();
    return true;
  };

  const commit = (value: Note[], details: PianoRollCommitEventDetails) => {
    options.onValueCommitted?.(value, details);
  };

  /** Ends the editing, dropping the held notes: the controlled value rules again. */
  const endEditing = () => {
    editing = false;
    dragValue = null;
    notify();
  };

  /** Proposes a selection; returns whether it was applied. */
  const select = (
    ids: readonly NoteId[],
    details: PianoRollSelectionEventDetails
  ) => {
    const current = selectedIds();
    if (ids.length === current.size && ids.every((id) => current.has(id))) {
      return false;
    }
    options.onSelectionChange?.(ids, details);
    if (details.isCanceled) {
      return false;
    }
    if (options.selection === undefined) {
      uncontrolledSelection = ids;
      selectionFor = null;
    }
    notify();
    return true;
  };

  const createId = (): NoteId => {
    if (options.createNoteId) {
      return options.createNoteId();
    }
    const taken = new Set(displayed().map((note) => note.id));
    let id = `note-${nextId}`;
    while (taken.has(id)) {
      nextId += 1;
      id = `note-${nextId}`;
    }
    nextId += 1;
    return id;
  };

  const sound = (pitch: number, details: PianoRollNoteOnEventDetails) => {
    if (options.disabled) {
      return false;
    }
    options.onNoteOn?.(pitch, details);
    if (details.isCanceled) {
      return false;
    }
    lastPitch = pitch;
    sounding = new Set(sounding).add(pitch);
    notify();
    return true;
  };

  const silence = (pitch: number, details: PianoRollNoteOffEventDetails) => {
    const next = new Set(sounding);
    next.delete(pitch);
    sounding = next;
    notify();
    options.onNoteOff?.(pitch, details);
  };

  /** The velocity a note drawn or played gets, when the roll has none to give it. */
  const template = () => {
    const length = bounds().minLength;
    return drawTemplate ?? { length, velocity: 1 };
  };

  const remember = (id: NoteId) => {
    const latest = displayed().find((note) => note.id === id);
    drawTemplate = {
      length: drawTemplate?.length ?? bounds().minLength,
      velocity: latest?.velocity ?? 1,
    };
  };

  /** Applies an edit from the keyboard and commits it at once; returns whether it was applied. */
  const applyKeyboard = (
    next: Note[],
    edit: PianoRollEdit,
    event: KeyboardEvent
  ) => {
    const details = Object.assign(createChangeEventDetails("keyboard", event), {
      edit,
    }) as PianoRollChangeEventDetails;
    if (!change(next, details)) {
      return false;
    }
    commit(next, {
      edit,
      event,
      reason: "keyboard",
    } as PianoRollCommitEventDetails);
    return true;
  };

  /** Adds a note at `start` on `pitch`, of the length and velocity last drawn; returns it with the notes it made, or null. */
  const addNote = (
    start: number,
    pitch: number,
    reason: "double-click" | "draw" | "keyboard",
    event: Event
  ): { note: Note; notes: Note[] } | null => {
    const { length, velocity } = template();
    const note = sanitizeNote(
      { id: createId(), length, pitch, start, velocity },
      bounds()
    );
    const details = Object.assign(createChangeEventDetails(reason, event), {
      edit: "add" as const,
    }) as PianoRollChangeEventDetails;
    const notes = [...displayed(), note];
    if (!change(notes, details)) {
      return null;
    }
    select(
      [note.id],
      createChangeEventDetails(reason, event) as PianoRollSelectionEventDetails
    );
    return { note, notes };
  };

  /** The timeline's units per px of the grid, which a drag converts with. */
  const unitsPerPixel = (grid: Element): number => {
    const { duration, zoom } = options.timeline;
    if (zoom !== null) {
      return 1 / zoom;
    }
    const { width } = grid.getBoundingClientRect();
    return duration / Math.max(width, 1);
  };

  /** How far apart, in px, a stroke is followed over `element`: at most a grid cell, so none is missed. */
  const cellSpacing = (element: Element) => {
    const { step } = options.timeline.grid;
    return step > 0
      ? Math.min(STROKE_SAMPLE_PX, step / unitsPerPixel(element))
      : STROKE_SAMPLE_PX;
  };

  /** Where a note drawn under the pointer starts: the grid cell it is in. */
  const startAt = (
    grid: Element,
    event: { clientX: number; ctrlKey?: boolean; metaKey?: boolean }
  ) => {
    const { duration, grid: cells, zoom } = options.timeline;
    const raw = timeAt(grid, event.clientX, zoom, duration);
    return bypassesGrid(event) ? raw : cellStart(raw, cells);
  };

  /** The pitch of the row under `clientY`. */
  const pitchAt = (grid: Element, clientY: number): number => {
    const rows = rowsFor(displayed());
    const count = rows.pitches.length;
    const rect = grid.getBoundingClientRect();
    const row = clamp(
      Math.floor(((clientY - rect.top) / rect.height) * count),
      0,
      count - 1
    );
    return rows.pitchAt(row);
  };

  /** The notes a key press or a drag acts on: the selection, when the note is part of it. */
  const targetsOf = (id: NoteId): ReadonlySet<NoteId> =>
    selectedIds().has(id) ? selectedIds() : new Set([id]);

  const removeNotes = (
    anchor: NoteId,
    ids: ReadonlySet<NoteId>,
    reason: "double-click" | "keyboard",
    event: KeyboardEvent | MouseEvent
  ) => {
    const base = displayed();
    const order = spatialOrder(base);
    const index = order.findIndex((other) => other.id === anchor);
    const kept = (other: Note) => !ids.has(other.id);
    const neighbour =
      order.slice(index + 1).find(kept) ?? order.slice(0, index).findLast(kept);
    const next = base.filter(kept);
    const details = Object.assign(createChangeEventDetails(reason, event), {
      edit: "remove" as const,
    }) as PianoRollChangeEventDetails;
    if (!change(next, details)) {
      return;
    }
    commit(next, {
      edit: "remove",
      event,
      reason,
    } as PianoRollCommitEventDetails);
    select(
      [...selectedIds()].filter((id) => !ids.has(id)),
      createChangeEventDetails(reason, event) as PianoRollSelectionEventDetails
    );
    if (reason === "keyboard") {
      options.requestFocus?.(neighbour?.id ?? null);
    }
  };

  /** Adds `id` to the selection, or takes it out. */
  const toggleSelected = (
    id: NoteId,
    event: PointerEvent | KeyboardEvent,
    reason: "press" | "keyboard"
  ) => {
    const selection = selectedIds();
    const next = selection.has(id)
      ? [...selection].filter((other) => other !== id)
      : [...selection, id];
    select(
      next,
      createChangeEventDetails(reason, event) as PianoRollSelectionEventDetails
    );
  };

  /** Sounds `pitch` instead of the pitch the gesture was sounding. */
  const audition = (
    current: NoteGesture,
    pitch: number,
    event: PointerEvent,
    velocity: number
  ) => {
    if (current.sounding === pitch) {
      return;
    }
    if (current.sounding !== null) {
      silence(current.sounding, { event, reason: "drag" });
    }
    const details = Object.assign(createChangeEventDetails("drag", event), {
      velocity,
    }) as PianoRollNoteOnEventDetails;
    current.sounding = sound(pitch, details) ? pitch : null;
  };

  /** Swaps the notes being dragged for copies left on top of them. */
  const copyNotes = (current: NoteGesture, event: PointerEvent) => {
    const { copyOf, notes } = duplicateNotes(
      current.origin,
      current.ids,
      createId
    );
    const details = Object.assign(createChangeEventDetails("drag", event), {
      edit: "duplicate" as const,
    }) as PianoRollChangeEventDetails;
    if (!change(notes, details)) {
      return;
    }
    current.origin = notes;
    current.ids = new Set(copyOf.values());
    current.anchor = {
      ...current.anchor,
      id: copyOf.get(current.anchor.id) ?? current.anchor.id,
    };
    current.edit = "duplicate";
    select(
      [...current.ids],
      createChangeEventDetails("drag", event) as PianoRollSelectionEventDetails
    );
  };

  /** Moves a note's velocity or chance by `delta`, and that of the selection with it when the note is part of it. */
  const nudgeLevel = (
    id: NoteId,
    level: NoteLevel,
    delta: number,
    reason: "input-change" | "keyboard",
    event: Event
  ) => {
    const next = changeLevel(displayed(), targetsOf(id), level, delta);
    const details = Object.assign(createChangeEventDetails(reason, event), {
      edit: level,
    }) as PianoRollChangeEventDetails;
    if (!change(next, details)) {
      return;
    }
    commit(next, {
      edit: level,
      event,
      reason,
    } as PianoRollCommitEventDetails);
    if (level === "velocity") {
      remember(id);
    }
  };

  // ---- grid

  const moveGrid = (event: PointerEvent, from: { x: number; y: number }) => {
    const current = gridGesture;
    if (!current) {
      return;
    }
    if (current.kind === "marquee") {
      moveMarquee(current, event);
      return;
    }
    if (current.kind === "paint") {
      // Every cell between the last move and this one is painted.
      const spacing = cellSpacing(current.grid);
      for (const point of strokePoints(
        from,
        event.clientX,
        event.clientY,
        spacing
      )) {
        movePaint(current, event, point);
      }
      return;
    }
    moveDraw(current, event);
  };

  /** Adds a note one grid cell long at `start` on `pitch`, painted by a drag; returns it, or null. */
  const paintNote = (start: number, pitch: number, event: PointerEvent) => {
    const cells = options.timeline.grid;
    const note = sanitizeNote(
      {
        id: createId(),
        length: cells.step > 0 ? cells.step : template().length,
        pitch,
        start,
        velocity: template().velocity,
      },
      bounds()
    );
    const details = Object.assign(createChangeEventDetails("draw", event), {
      edit: "add" as const,
    }) as PianoRollChangeEventDetails;
    return change([...displayed(), note], details) ? note : null;
  };

  /** Sounds `pitch` in place of what the painting was sounding. */
  const soundPainted = (
    current: Extract<GridGesture, { kind: "paint" }>,
    pitch: number,
    event: PointerEvent
  ) => {
    if (current.sounding === pitch) {
      return;
    }
    if (current.sounding !== null) {
      silence(current.sounding, { event, reason: "draw" });
    }
    const details = Object.assign(createChangeEventDetails("draw", event), {
      velocity: template().velocity,
    }) as PianoRollNoteOnEventDetails;
    current.sounding = sound(pitch, details) ? pitch : null;
  };

  const movePaint = (
    current: Extract<GridGesture, { kind: "paint" }>,
    event: PointerEvent,
    at: { x: number; y: number }
  ) => {
    const start = startAt(current.grid, {
      clientX: at.x,
      ctrlKey: event.ctrlKey,
      metaKey: event.metaKey,
    });
    if (current.cells.has(start)) {
      return;
    }
    const pitch = event.altKey ? current.pitch : pitchAt(current.grid, at.y);
    const note = paintNote(start, pitch, event);
    if (!note) {
      return;
    }
    current.cells.add(start);
    current.ids.push(note.id);
    select(
      [...current.ids],
      createChangeEventDetails("draw", event) as PianoRollSelectionEventDetails
    );
    soundPainted(current, pitch, event);
  };

  const moveMarquee = (
    current: Extract<GridGesture, { kind: "marquee" }>,
    event: PointerEvent
  ) => {
    const rect = current.grid.getBoundingClientRect();
    const x = clamp(event.clientX - rect.left, 0, rect.width);
    const y = clamp(event.clientY - rect.top, 0, rect.height);
    band = {
      height: Math.abs(y - current.y),
      left: Math.min(x, current.x),
      top: Math.min(y, current.y),
      width: Math.abs(x - current.x),
    };
    const perPixel = unitsPerPixel(current.grid);
    const rowHeight = rect.height / rowsFor(displayed()).pitches.length;
    const within = notesWithin(
      displayed(),
      {
        end: (band.left + band.width) * perPixel,
        firstRow: Math.floor(band.top / rowHeight),
        lastRow: Math.ceil((band.top + band.height) / rowHeight) - 1,
        start: band.left * perPixel,
      },
      rowsFor(displayed()).rowOf
    );
    select(
      [...new Set([...current.base, ...within])],
      createChangeEventDetails(
        "marquee",
        event
      ) as PianoRollSelectionEventDetails
    );
    notify();
  };

  const moveDraw = (
    current: Extract<GridGesture, { kind: "draw" }>,
    event: PointerEvent
  ) => {
    const dx = event.clientX - current.startX;
    const dy = event.clientY - current.startY;
    if (!current.started && dx * dx + dy * dy < DRAG_THRESHOLD ** 2) {
      return;
    }
    current.started = true;
    const { duration, grid, zoom } = options.timeline;
    const raw = timeAt(current.grid, event.clientX, zoom, duration);
    const end = bypassesGrid(event) ? raw : snapToGrid(raw, grid);
    const length = Math.min(
      duration - current.start,
      Math.max(bounds().minLength, end - current.start)
    );
    const next = displayed().map((note) =>
      note.id === current.id ? { ...note, length } : note
    );
    change(
      next,
      Object.assign(createChangeEventDetails("draw", event), {
        edit: "add" as const,
      }) as PianoRollChangeEventDetails
    );
  };

  const endGrid = (event: PointerEvent) => {
    const current = gridGesture;
    gridGesture = null;
    if (!current) {
      return;
    }
    if (current.kind === "marquee") {
      band = null;
      notify();
      return;
    }
    // Read before settling: the notes fall back to the known value after.
    const committed = [...displayed()];
    endEditing();
    const drawn =
      current.kind === "draw"
        ? committed.find((note) => note.id === current.id)
        : undefined;
    if (drawn) {
      drawTemplate = {
        length: drawn.length,
        velocity: drawTemplate?.velocity ?? 1,
      };
    }
    commit(committed, { edit: "add", event, reason: "draw" });
    if (current.sounding !== null) {
      silence(current.sounding, { event, reason: "draw" });
    }
  };

  /** Starts painting: the first note under the pointer, then one per cell the drag crosses. */
  const paintFrom = (event: PointerEvent, grid: Element) => {
    const start = startAt(grid, event);
    const pitch = pitchAt(grid, event.clientY);
    const note = paintNote(start, pitch, event);
    if (!note) {
      endEditing();
      return;
    }
    select([note.id], createChangeEventDetails("draw", event));
    grid.setPointerCapture?.(event.pointerId);
    const current: Extract<GridGesture, { kind: "paint" }> = {
      cells: new Set([note.start]),
      grid,
      ids: [note.id],
      kind: "paint",
      pitch: note.pitch,
      sounding: null,
    };
    gridGesture = current;
    soundPainted(current, note.pitch, event);
    pointers.follow(grid, event, moveGrid, endGrid);
  };

  const pressGrid: PianoRollController["pressGrid"] = (event, grid) => {
    if (options.disabled || event.button !== 0 || !pointers.claim(event)) {
      return;
    }
    if ((options.mode ?? "select") === "select") {
      if (!event.shiftKey) {
        select([], createChangeEventDetails("marquee", event));
      }
      grid.setPointerCapture?.(event.pointerId);
      const rect = grid.getBoundingClientRect();
      gridGesture = {
        base: event.shiftKey ? [...selectedIds()] : [],
        grid,
        kind: "marquee",
        x: event.clientX - rect.left,
        y: event.clientY - rect.top,
      };
      pointers.follow(grid, event, moveGrid, endGrid);
      return;
    }
    editing = true;
    notify();
    if (options.drawStyle === "paint") {
      paintFrom(event, grid);
      return;
    }
    const added = addNote(
      startAt(grid, event),
      pitchAt(grid, event.clientY),
      "draw",
      event
    );
    if (!added) {
      endEditing();
      return;
    }
    grid.setPointerCapture?.(event.pointerId);
    const soundingPitch = sound(
      added.note.pitch,
      Object.assign(createChangeEventDetails("draw", event), {
        velocity: added.note.velocity ?? 1,
      }) as PianoRollNoteOnEventDetails
    )
      ? added.note.pitch
      : null;
    gridGesture = {
      grid,
      id: added.note.id,
      kind: "draw",
      sounding: soundingPitch,
      start: added.note.start,
      started: false,
      startX: event.clientX,
      startY: event.clientY,
    };
    pointers.follow(grid, event, moveGrid, endGrid);
  };

  const doubleClickGrid: PianoRollController["doubleClickGrid"] = (
    event,
    grid
  ) => {
    if (options.disabled || (options.mode ?? "select") !== "select") {
      return;
    }
    const added = addNote(
      startAt(grid, event),
      pitchAt(grid, event.clientY),
      "double-click",
      event
    );
    if (added) {
      commit(added.notes, { edit: "add", event, reason: "double-click" });
    }
  };

  const keyGrid: PianoRollController["keyGrid"] = (event) => {
    if (options.disabled) {
      return false;
    }
    if (shortcut(event)) {
      return true;
    }
    if (event.key === "Escape") {
      select([], createChangeEventDetails("keyboard", event));
      return true;
    }
    if (event.key === "a" && (event.metaKey || event.ctrlKey)) {
      select(
        displayed().map((note) => note.id),
        createChangeEventDetails("keyboard", event)
      );
      return true;
    }
    return false;
  };

  const addAtPlayback: PianoRollController["addAtPlayback"] = (event) => {
    if (options.disabled) {
      return false;
    }
    const { pitches } = rowsFor(displayed());
    const pitch =
      lastPitch ?? pitches[Math.floor(pitches.length / 2)] ?? bounds().minPitch;
    const added = addNote(
      cellStart(options.timeline.position(), options.timeline.grid),
      pitch,
      "keyboard",
      event
    );
    if (!added) {
      return false;
    }
    commit(added.notes, { edit: "add", event, reason: "keyboard" });
    options.requestFocus?.(added.note.id);
    return true;
  };

  // ---- notes

  const moveNote = (event: PointerEvent) => {
    const current = noteGesture;
    if (!current) {
      return;
    }
    const dx = event.clientX - current.startX;
    const dy = event.clientY - current.startY;
    if (!current.started) {
      if (dx * dx + dy * dy < DRAG_THRESHOLD ** 2) {
        return;
      }
      current.started = true;
      if (current.copy) {
        copyNotes(current, event);
      }
    }
    const next = draggedNotes(
      current,
      dx * unitsPerPixel(current.grid),
      dy,
      bypassesGrid(event) ? NO_GRID : options.timeline.grid,
      bounds()
    );
    const details = Object.assign(createChangeEventDetails("drag", event), {
      edit: current.edit,
    }) as PianoRollChangeEventDetails;
    if (change(next, details)) {
      current.changed = true;
    }
    const moved = displayed().find((other) => other.id === current.anchor.id);
    if (moved) {
      audition(current, moved.pitch, event, current.anchor.velocity ?? 1);
    }
  };

  const endNote = (event: PointerEvent) => {
    const current = noteGesture;
    if (!current) {
      return;
    }
    noteGesture = null;
    // Read before settling: the notes fall back to the known value after.
    const committed = [...displayed()];
    endEditing();
    if (current.changed) {
      if (current.handle !== "move") {
        const resized = committed.find(
          (other) => other.id === current.anchor.id
        );
        if (resized) {
          drawTemplate = {
            length: resized.length,
            velocity: drawTemplate?.velocity ?? 1,
          };
        }
      }
      commit(committed, { edit: current.edit, event, reason: "drag" });
      if (current.edit === "duplicate") {
        // The copy is what was dragged: the keys should act on it next.
        options.requestFocus?.(current.anchor.id);
      }
    }
    if (current.sounding !== null) {
      silence(current.sounding, { event, reason: "drag" });
    }
  };

  const pressNote: PianoRollController["pressNote"] = (
    id,
    handle,
    event,
    element,
    grid
  ) => {
    if (options.disabled || !pointers.claim(event)) {
      return;
    }
    const selection = selectedIds();
    if (handle === "move" && event.shiftKey) {
      toggleSelected(id, event, "press");
      return;
    }
    let ids = selection;
    if (!selection.has(id)) {
      ids = new Set([id]);
      select([id], createChangeEventDetails("press", event));
    }
    const anchor = displayed().find((note) => note.id === id);
    if (!anchor) {
      return;
    }
    const rect = grid.getBoundingClientRect();
    element.setPointerCapture?.(event.pointerId);
    editing = true;
    notify();
    const rows = rowsFor(displayed());
    noteGesture = {
      anchor,
      changed: false,
      copy: handle === "move" && event.altKey,
      edit: handle === "move" ? "move" : "resize",
      grid,
      handle,
      ids,
      origin: [...displayed()],
      rowHeight: rect.height / rows.pitches.length,
      rows,
      sounding: null,
      started: false,
      startX: event.clientX,
      startY: event.clientY,
    };
    audition(noteGesture, anchor.pitch, event, anchor.velocity ?? 1);
    pointers.follow(element, event, moveNote, endNote);
  };

  const doubleClickNote: PianoRollController["doubleClickNote"] = (
    id,
    event
  ) => {
    if (!options.disabled) {
      removeNotes(id, new Set([id]), "double-click", event);
    }
  };

  const keyNote: PianoRollController["keyNote"] = (id, event) => {
    if (options.disabled) {
      return false;
    }
    if (event.key === "Delete" || event.key === "Backspace") {
      removeNotes(id, targetsOf(id), "keyboard", event);
      return true;
    }
    if (event.key === "Enter" || event.key === " ") {
      toggleSelected(id, event, "keyboard");
      return true;
    }
    const result = keyboardEdit(
      displayed(),
      targetsOf(id),
      event.key,
      event.shiftKey,
      options.timeline.step,
      bounds()
    );
    if (!result) {
      return false;
    }
    const before = displayed().find((note) => note.id === id)?.pitch;
    if (applyKeyboard(result.notes, result.edit, event)) {
      // Notes render in the order they are read, so a move can reorder them
      // and take the focus with it.
      options.requestFocus?.(id);
    }
    const after = displayed().find((note) => note.id === id);
    if (after && after.pitch !== before) {
      releaseKey(event);
      keySounding = sound(
        after.pitch,
        Object.assign(createChangeEventDetails("keyboard", event), {
          velocity: after.velocity ?? 1,
        }) as PianoRollNoteOnEventDetails
      )
        ? after.pitch
        : null;
    }
    return true;
  };

  const releaseKey: PianoRollController["releaseKey"] = (event) => {
    if (keySounding === null) {
      return;
    }
    silence(keySounding, {
      event: event as FocusEvent | KeyboardEvent,
      reason: "keyboard",
    } as PianoRollNoteOffEventDetails);
    keySounding = null;
  };

  // ---- velocity

  const moveVelocity = (event: PointerEvent) => {
    const current = velocityGesture;
    if (!current?.height) {
      return;
    }
    // Up is louder, or likelier: the bar follows the pointer.
    const delta = (current.startY - event.clientY) / current.height;
    const next = current.deviation
      ? setDeviation(current.origin, current.ids, delta)
      : changeLevel(current.origin, current.ids, current.level, delta);
    const details = Object.assign(createChangeEventDetails("drag", event), {
      edit: velocityEdit(current),
    }) as PianoRollChangeEventDetails;
    if (change(next, details)) {
      current.changed = true;
    }
  };

  const endVelocity = (event: PointerEvent) => {
    const current = velocityGesture;
    if (!current) {
      return;
    }
    velocityGesture = null;
    // Read before settling: the notes fall back to the known value after.
    const committed = [...displayed()];
    endEditing();
    if (current.changed) {
      commit(committed, { edit: velocityEdit(current), event, reason: "drag" });
      if (current.level === "velocity") {
        remember(current.id);
      }
    }
  };

  const pressVelocity: PianoRollController["pressVelocity"] = (
    id,
    event,
    element,
    lane,
    level = "velocity"
  ) => {
    if (options.disabled || event.button !== 0 || !pointers.claim(event)) {
      return;
    }
    const selection = selectedIds();
    if (event.shiftKey) {
      toggleSelected(id, event, "press");
      return;
    }
    // In draw mode the lane is a brush: the bars follow the pointer's height.
    if (
      (options.mode ?? "select") === "draw" &&
      lane &&
      !(event.metaKey || event.ctrlKey)
    ) {
      paintLevels(event, lane, level);
      return;
    }
    let ids = selection;
    if (!selection.has(id)) {
      ids = new Set([id]);
      select([id], createChangeEventDetails("press", event));
    }
    element.setPointerCapture?.(event.pointerId);
    editing = true;
    notify();
    velocityGesture = {
      changed: false,
      deviation: level === "velocity" && (event.metaKey || event.ctrlKey),
      height: lane?.getBoundingClientRect().height ?? 0,
      id,
      ids,
      level,
      origin: [...displayed()],
      startY: event.clientY,
    };
    pointers.follow(element, event, moveVelocity, endVelocity);
  };

  const keyVelocity: PianoRollController["keyVelocity"] = (
    id,
    event,
    level = "velocity"
  ) => {
    if (options.disabled) {
      return false;
    }
    const velocity = displayed().find((note) => note.id === id)?.[level] ?? 1;
    const target = {
      ArrowDown: velocity - VELOCITY_STEP,
      ArrowLeft: velocity - VELOCITY_STEP,
      ArrowRight: velocity + VELOCITY_STEP,
      ArrowUp: velocity + VELOCITY_STEP,
      End: 1,
      Home: 0,
      PageDown: velocity - VELOCITY_LARGE_STEP,
      PageUp: velocity + VELOCITY_LARGE_STEP,
    }[event.key];
    if (target === undefined) {
      return false;
    }
    nudgeLevel(id, level, target - velocity, "keyboard", event);
    return true;
  };

  const setVelocity: PianoRollController["setVelocity"] = (
    id,
    value,
    event,
    level = "velocity"
  ) => {
    const current = displayed().find((note) => note.id === id)?.[level] ?? 1;
    nudgeLevel(id, level, value - current, "input-change", event);
  };

  // ---- painting a lane

  /** Sets the bars in the grid cell under the pointer to its height. */
  const movePaintLevel = (
    event: PointerEvent,
    at: { x: number; y: number } = { x: event.clientX, y: event.clientY }
  ) => {
    const current = paintLevelGesture;
    if (!current) {
      return;
    }
    const rect = current.lane.getBoundingClientRect();
    if (rect.height <= 0) {
      return;
    }
    const { duration, grid, zoom } = options.timeline;
    const time = timeAt(current.lane, at.x, zoom, duration);
    const from = grid.step > 0 ? cellStart(time, grid) : time;
    const to = grid.step > 0 ? from + grid.step : time;
    const value = clamp(1 - (at.y - rect.top) / rect.height, 0, 1);
    const hit = (note: Note) =>
      grid.step > 0 ? note.start >= from && note.start < to : false;
    const next = displayed().map((note) =>
      hit(note) && note[current.level] !== value
        ? { ...note, [current.level]: value }
        : note
    );
    const details = Object.assign(createChangeEventDetails("draw", event), {
      edit: current.level,
    }) as PianoRollChangeEventDetails;
    if (change(next, details)) {
      current.changed = true;
    }
  };

  const endPaintLevel = (event: PointerEvent) => {
    const current = paintLevelGesture;
    if (!current) {
      return;
    }
    paintLevelGesture = null;
    // Read before settling: the notes fall back to the known value after.
    const committed = [...displayed()];
    endEditing();
    if (current.changed) {
      commit(committed, { edit: current.level, event, reason: "draw" });
    }
  };

  const paintLevels: PianoRollController["paintLevels"] = (
    event,
    lane,
    level = "velocity"
  ) => {
    if (
      options.disabled ||
      event.button !== 0 ||
      !pointers.claim(event) ||
      (options.mode ?? "select") !== "draw"
    ) {
      return;
    }
    event.preventDefault();
    lane.setPointerCapture?.(event.pointerId);
    editing = true;
    notify();
    paintLevelGesture = { changed: false, lane, level };
    movePaintLevel(event);
    pointers.follow(
      lane,
      event,
      (move, from) => {
        const spacing = cellSpacing(lane);
        for (const point of strokePoints(
          from,
          move.clientX,
          move.clientY,
          spacing
        )) {
          movePaintLevel(move, point);
        }
      },
      endPaintLevel
    );
  };

  // ---- stretch

  const moveStretch = (event: PointerEvent) => {
    const current = stretchGesture;
    if (!current) {
      return;
    }
    const { duration, grid, zoom } = options.timeline;
    const raw = timeAt(current.grid, event.clientX, zoom, duration);
    const edge = bypassesGrid(event) ? raw : snapToGrid(raw, grid);
    const factor = (edge - current.anchor) / (current.moving - current.anchor);
    if (!(factor > 0)) {
      return;
    }
    const next = stretchNotes(
      current.origin,
      current.ids,
      factor,
      bounds(),
      current.anchor
    );
    const details = Object.assign(createChangeEventDetails("drag", event), {
      edit: "stretch" as const,
    }) as PianoRollChangeEventDetails;
    if (change(next, details)) {
      current.changed = true;
    }
  };

  const endStretch = (event: PointerEvent) => {
    const current = stretchGesture;
    if (!current) {
      return;
    }
    stretchGesture = null;
    // Read before settling: the notes fall back to the known value after.
    const committed = [...displayed()];
    endEditing();
    if (current.changed) {
      commit(committed, { edit: "stretch", event, reason: "drag" });
    }
  };

  const pressStretch: PianoRollController["pressStretch"] = (
    edge,
    event,
    element,
    grid
  ) => {
    if (options.disabled || event.button !== 0 || !pointers.claim(event)) {
      return;
    }
    const ids = selectedIds();
    const span = selectionSpan(displayed(), ids);
    if (!span || span.end <= span.start) {
      return;
    }
    event.preventDefault();
    element.setPointerCapture?.(event.pointerId);
    editing = true;
    notify();
    stretchGesture = {
      anchor: edge === "end" ? span.start : span.end,
      changed: false,
      edge,
      grid,
      ids,
      moving: edge === "end" ? span.end : span.start,
      origin: [...displayed()],
    };
    pointers.follow(element, event, moveStretch, endStretch);
  };

  // ---- keys and commands

  const shortcut: PianoRollController["shortcut"] = (event) => {
    if (event.altKey) {
      return false;
    }
    const key = event.key.toLowerCase();
    const cells = options.timeline.grid;
    const copy = (cut: boolean) => {
      const chosen = selectedIds();
      if (chosen.size === 0) {
        return;
      }
      const current = displayed();
      clipboard = current.filter((note) => chosen.has(note.id));
      if (cut) {
        applyKeyboard(
          current.filter((note) => !chosen.has(note.id)),
          "remove",
          event
        );
        select([], createChangeEventDetails("keyboard", event));
      }
    };
    const duplicate = () => {
      const result = duplicateAfter(
        displayed(),
        selectedIds(),
        createId,
        bounds()
      );
      if (result && applyKeyboard(result.notes, "duplicate", event)) {
        select(result.copies, createChangeEventDetails("keyboard", event));
      }
    };
    const paste = () => {
      const result = pasteNotes(
        displayed(),
        clipboard,
        cellStart(options.timeline.position(), cells),
        createId,
        bounds()
      );
      if (result && applyKeyboard(result.notes, "paste", event)) {
        select(result.pasted, createChangeEventDetails("keyboard", event));
      }
    };
    // As in a DAW: with nothing selected, everything is quantized.
    const quantize = () => {
      const current = displayed();
      const chosen = selectedIds();
      const ids =
        chosen.size > 0 ? chosen : new Set(current.map((note) => note.id));
      applyKeyboard(
        quantizeNotes(
          current,
          ids,
          (start) => snapToGrid(start, cells),
          bounds()
        ),
        "quantize",
        event
      );
    };
    // With Shift the keys are left to the editor around the roll, such as Cmd+Shift+D to duplicate time.
    if (event.shiftKey) {
      return false;
    }
    const commands: Record<string, (() => void) | undefined> =
      event.metaKey || event.ctrlKey
        ? {
            c: () => copy(false),
            d: duplicate,
            v: paste,
            x: () => copy(true),
          }
        : { q: quantize };
    const run = commands[key];
    run?.();
    return run !== undefined;
  };

  const keyOn: PianoRollController["keyOn"] = (pitch, details) => {
    if (!details.event.shiftKey) {
      sound(
        pitch,
        Object.assign(details, { velocity: 1 }) as PianoRollNoteOnEventDetails
      );
      return;
    }
    details.cancel();
    if (details.reason === "glide") {
      return;
    }
    // Takes every note on the row, or gives them all back.
    const row = displayed()
      .filter((note) => note.pitch === pitch)
      .map((note) => note.id);
    if (row.length === 0) {
      return;
    }
    const selection = selectedIds();
    const all = row.every((id) => selection.has(id));
    select(
      all
        ? [...selection].filter((id) => !row.includes(id))
        : [...new Set([...selection, ...row])],
      createChangeEventDetails(
        details.reason,
        details.event
      ) as PianoRollSelectionEventDetails
    );
  };

  const keyOff: PianoRollController["keyOff"] = (pitch, details) => {
    silence(pitch, details);
  };

  return {
    addAtPlayback,
    doubleClickGrid,
    doubleClickNote,
    getSnapshot,
    keyGrid,
    keyNote,
    keyOff,
    keyOn,
    keyVelocity,
    pressGrid,
    pressNote,
    pressStretch,
    paintLevels,
    pressVelocity,
    releaseKey,
    setOptions: (next) => {
      options = next;
    },
    setVelocity,
    shortcut,
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

import { type Grid, snapMove } from "../grid";
import { pitchClassOf, type RollScale } from "./rows";

/** A note's id: unique within its clip. */
export type NoteId = number | string;

/** A note on the roll: its pitch, start and length, how hard and how likely it plays, how far its velocity may stray, and whether it is deactivated. */
export interface Note {
  /** How likely the note is to play each time it comes round, 0…1. @default 1 */
  chance?: number;
  /** How far the velocity may stray each time the note plays, up (positive) or down, as a share of the full range. @default 0 */
  deviation?: number;
  id: NoteId;
  /** Length, in the timeline's units. */
  length: number;
  /** Whether the note is deactivated: it stays on the roll, and does not play. @default false */
  muted?: boolean;
  /** MIDI pitch: 60 is middle C. */
  pitch: number;
  /** Where the note starts, in the timeline's units. */
  start: number;
  /** How hard the note is played, 0…1. @default 1 */
  velocity?: number;
}

/** What every edit keeps a note within: the timeline's length, the pitch range and the shortest length. */
export interface RollBounds {
  duration: number;
  maxPitch: number;
  minLength: number;
  minPitch: number;
}

/** Keeps a note on the roll: inside the timeline, in the pitch range, at least `minLength` long. */
export function sanitizeNote(note: Note, bounds: RollBounds): Note {
  const length = Math.min(
    bounds.duration,
    Math.max(bounds.minLength, Number.isFinite(note.length) ? note.length : 0)
  );
  return {
    ...note,
    length,
    pitch: Math.min(
      bounds.maxPitch,
      Math.max(bounds.minPitch, Math.round(note.pitch))
    ),
    start: Math.min(
      bounds.duration - length,
      Math.max(0, Number.isFinite(note.start) ? note.start : 0)
    ),
    velocity: Math.min(1, Math.max(0, note.velocity ?? 1)),
  };
}

/**
 * Moves the notes in `ids` by the same amount, in time and in pitch, so a
 * chord keeps its spacing. The whole group stops where its most restricted
 * note would leave the roll, rather than squashing against the edge.
 */
export function moveNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  deltaStart: number,
  deltaPitch: number,
  bounds: RollBounds
): Note[] {
  const moving = notes.filter((note) => ids.has(note.id));
  if (moving.length === 0) {
    return [...notes];
  }
  const earliest = Math.min(...moving.map((note) => note.start));
  const latestEnd = Math.max(...moving.map((note) => note.start + note.length));
  const lowest = Math.min(...moving.map((note) => note.pitch));
  const highest = Math.max(...moving.map((note) => note.pitch));
  const time = Math.min(
    bounds.duration - latestEnd,
    Math.max(-earliest, deltaStart)
  );
  const pitch = Math.min(
    bounds.maxPitch - highest,
    Math.max(bounds.minPitch - lowest, Math.round(deltaPitch))
  );
  return notes.map((note) =>
    ids.has(note.id)
      ? { ...note, pitch: note.pitch + pitch, start: note.start + time }
      : note
  );
}

/**
 * Moves one edge of every note in `ids` by `delta`: the end makes them
 * longer or shorter, the start trims them from the front while their end
 * stays put. None gets shorter than `minLength` or leaves the timeline.
 */
export function resizeNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  edge: "end" | "start",
  delta: number,
  bounds: RollBounds
): Note[] {
  const resizing = notes.filter((note) => ids.has(note.id));
  if (resizing.length === 0) {
    return [...notes];
  }
  let amount = delta;
  for (const note of resizing) {
    if (edge === "end") {
      amount = Math.max(amount, bounds.minLength - note.length);
      amount = Math.min(amount, bounds.duration - note.start - note.length);
    } else {
      amount = Math.min(amount, note.length - bounds.minLength);
      amount = Math.max(amount, -note.start);
    }
  }
  return notes.map((note) => {
    if (!ids.has(note.id)) {
      return note;
    }
    return edge === "end"
      ? { ...note, length: note.length + amount }
      : { ...note, length: note.length - amount, start: note.start + amount };
  });
}

/** How far the edge of `note` moves when dragged by `delta`, on the grid unless `grid.step` is 0. */
export function snapEdgeDelta(
  note: Note,
  edge: "end" | "start",
  delta: number,
  grid: Grid
): number {
  const from = edge === "end" ? note.start + note.length : note.start;
  return snapMove(from + delta, from, grid) - from;
}

/**
 * Copies of the notes in `ids`, under new ids from `nextId`, left where the
 * originals are. `copyOf` maps each original's id to its copy's.
 */
export function duplicateNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  nextId: () => NoteId
): { copyOf: Map<NoteId, NoteId>; notes: Note[] } {
  const copyOf = new Map<NoteId, NoteId>();
  const copies: Note[] = [];
  for (const note of notes) {
    if (ids.has(note.id)) {
      const id = nextId();
      copyOf.set(note.id, id);
      copies.push({ ...note, id });
    }
  }
  return { copyOf, notes: [...notes, ...copies] };
}

/**
 * Copies of the notes in `ids` placed right after them, one selection's
 * length on, so a phrase repeats itself the way it is played. They stop where
 * the roll ends; with no room for even a step, nothing is copied.
 */
export function duplicateAfter(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  nextId: () => NoteId,
  bounds: RollBounds
): { copies: NoteId[]; notes: Note[] } | null {
  const source = notes.filter((note) => ids.has(note.id));
  if (source.length === 0) {
    return null;
  }
  const earliest = Math.min(...source.map((note) => note.start));
  const latestEnd = Math.max(...source.map((note) => note.start + note.length));
  const shift = Math.min(latestEnd - earliest, bounds.duration - latestEnd);
  if (shift < bounds.minLength) {
    return null;
  }
  const copies = source.map((note) => ({
    ...note,
    id: nextId(),
    start: note.start + shift,
  }));
  return {
    copies: copies.map((note) => note.id),
    notes: [...notes, ...copies],
  };
}

/** The notes in `ids` with their start on the nearest grid line: their length, and the rest, stay. */
export function quantizeNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  snap: (value: number) => number,
  bounds: RollBounds
): Note[] {
  return notes.map((note) => {
    if (!ids.has(note.id)) {
      return note;
    }
    const start = Math.min(
      bounds.duration - note.length,
      Math.max(0, snap(note.start))
    );
    return start === note.start ? note : { ...note, start };
  });
}

/**
 * Copies of `clipboard` under new ids, the earliest starting at `at`: a phrase
 * keeps its spacing wherever it lands, and stops where the roll ends.
 */
export function pasteNotes(
  notes: readonly Note[],
  clipboard: readonly Note[],
  at: number,
  nextId: () => NoteId,
  bounds: RollBounds
): { pasted: NoteId[]; notes: Note[] } | null {
  if (clipboard.length === 0) {
    return null;
  }
  const earliest = Math.min(...clipboard.map((note) => note.start));
  const latestEnd = Math.max(
    ...clipboard.map((note) => note.start + note.length)
  );
  const shift = Math.max(
    -earliest,
    Math.min(at - earliest, bounds.duration - latestEnd)
  );
  const pasted = clipboard.map((note) => ({
    ...note,
    id: nextId(),
    start: note.start + shift,
  }));
  return {
    notes: [...notes, ...pasted],
    pasted: pasted.map((note) => note.id),
  };
}

/** The ids of the notes overlapping a stretch of time and a band of rows. */
export function notesWithin(
  notes: readonly Note[],
  area: { end: number; firstRow: number; lastRow: number; start: number },
  rowOf: (pitch: number) => number
): NoteId[] {
  return notes
    .filter((note) => {
      const row = rowOf(note.pitch);
      return (
        note.start < area.end &&
        note.start + note.length > area.start &&
        row >= area.firstRow &&
        row <= area.lastRow
      );
    })
    .map((note) => note.id);
}

/** Notes in the order the eye reads them: left to right, then top to bottom. */
export function spatialOrder(notes: readonly Note[]): Note[] {
  return [...notes].sort((a, b) => a.start - b.start || b.pitch - a.pitch);
}

/** Whether two lists hold the same notes, in the same order. */
export function sameNotes(a: readonly Note[], b: readonly Note[]): boolean {
  return (
    a.length === b.length &&
    a.every((note, index) => {
      const other = b[index];
      return (
        other !== undefined &&
        note.id === other.id &&
        note.pitch === other.pitch &&
        note.start === other.start &&
        note.length === other.length &&
        note.velocity === other.velocity &&
        note.muted === other.muted &&
        note.chance === other.chance &&
        note.deviation === other.deviation
      );
    })
  );
}

/** The start of the grid cell `value` falls in: where a note drawn there begins. */
export function cellStart(value: number, grid: Grid): number {
  if (!(grid.step > 0)) {
    return value;
  }
  return (
    Math.floor((value - grid.offset) / grid.step) * grid.step + grid.offset
  );
}

/** Shift + Arrow Up/Down moves notes by an octave. */
const OCTAVE = 12;

/**
 * What an arrow key does to the notes in `ids`: Left and Right move them by
 * `step`, or with Shift change their length; Up and Down move them by a
 * semitone, or with Shift an octave. Any other key does nothing.
 */
export function keyboardEdit(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  key: string,
  shiftKey: boolean,
  step: number,
  bounds: RollBounds
): { edit: "move" | "resize"; notes: Note[] } | null {
  const direction = key === "ArrowRight" || key === "ArrowUp" ? 1 : -1;
  if (key === "ArrowLeft" || key === "ArrowRight") {
    return shiftKey
      ? {
          edit: "resize",
          notes: resizeNotes(notes, ids, "end", direction * step, bounds),
        }
      : {
          edit: "move",
          notes: moveNotes(notes, ids, direction * step, 0, bounds),
        };
  }
  if (key === "ArrowUp" || key === "ArrowDown") {
    const semitones = direction * (shiftKey ? OCTAVE : 1);
    return { edit: "move", notes: moveNotes(notes, ids, 0, semitones, bounds) };
  }
  return null;
}

/**
 * Changes the velocity of every note in `ids` by `delta`, each kept within
 * 0…1: a phrase keeps its dynamics, where setting them all to one value
 * would flatten it.
 */
export function changeVelocity(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  delta: number
): Note[] {
  return changeLevel(notes, ids, "velocity", delta);
}

/** A note's value a lane draws as a bar, 0…1: how hard it plays, or how likely it is to. */
export type NoteLevel = "chance" | "velocity";

/**
 * Changes `level` of every note in `ids` by `delta`, each kept within 0…1, so
 * the notes keep their differences: the velocity, or the chance to play.
 */
export function changeLevel(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  level: NoteLevel,
  delta: number
): Note[] {
  return notes.map((note) =>
    ids.has(note.id)
      ? {
          ...note,
          [level]: Math.min(1, Math.max(0, (note[level] ?? 1) + delta)),
        }
      : note
  );
}

/** Sets how far the velocity of the notes in `ids` may stray each time they play, kept within -1…1. */
export function setDeviation(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  deviation: number
): Note[] {
  const value = Math.min(1, Math.max(-1, deviation));
  return notes.map((note) =>
    ids.has(note.id) ? { ...note, deviation: value } : note
  );
}

/** The notes in `ids`, with the earliest start and the latest end among them. */
function span(notes: readonly Note[], ids: ReadonlySet<NoteId>) {
  const chosen = notes.filter((note) => ids.has(note.id));
  return {
    chosen,
    earliest: Math.min(...chosen.map((note) => note.start)),
    latestEnd: Math.max(...chosen.map((note) => note.start + note.length)),
  };
}

/** Cuts a note at each time in `at` it holds: the first piece keeps its id, the others take new ones. */
function cut(note: Note, at: readonly number[], nextId: () => NoteId): Note[] {
  const end = note.start + note.length;
  const times = at.filter((time) => time > note.start && time < end);
  const edges = [note.start, ...times, end];
  return edges.slice(0, -1).map((start, index) => ({
    ...note,
    id: index === 0 ? note.id : nextId(),
    length: (edges[index + 1] as number) - start,
    start,
  }));
}

function cutNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  timesOf: (note: Note) => number[],
  nextId: () => NoteId
): { added: NoteId[]; notes: Note[] } {
  const added: NoteId[] = [];
  const next = notes.flatMap((note) => {
    if (!ids.has(note.id)) {
      return [note];
    }
    const pieces = cut(note, timesOf(note), nextId);
    added.push(...pieces.slice(1).map((piece) => piece.id));
    return pieces;
  });
  return { added, notes: next };
}

/**
 * Splits the notes in `ids` at `at`, or at each time in it, wherever a note
 * holds that time: the first piece keeps the note's id, the others take new
 * ones. Every grid line as `at` chops the notes to the grid. `added` lists
 * the new ids.
 */
export function splitNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  at: number | readonly number[],
  nextId: () => NoteId
): { added: NoteId[]; notes: Note[] } {
  const times = typeof at === "number" ? [at] : at;
  return cutNotes(notes, ids, () => [...times], nextId);
}

/**
 * Chops each note in `ids` into `parts` notes of the same length, as many as
 * fit at `minLength` or longer: a held note becomes a repeated one.
 */
export function chopNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  parts: number,
  nextId: () => NoteId,
  minLength: number
): { added: NoteId[]; notes: Note[] } {
  return cutNotes(
    notes,
    ids,
    (note) => {
      const count = Math.max(
        1,
        Math.min(Math.floor(parts), Math.floor(note.length / minLength))
      );
      const piece = note.length / count;
      return Array.from(
        { length: count - 1 },
        (_, index) => note.start + piece * (index + 1)
      );
    },
    nextId
  );
}

/**
 * Joins the notes in `ids` that share a pitch into one, from the earliest
 * start to the latest end: the earliest keeps its id and velocity.
 */
export function joinNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>
): Note[] {
  const joined = new Map<number, Note>();
  for (const note of spatialOrder(notes)) {
    if (!ids.has(note.id)) {
      continue;
    }
    const first = joined.get(note.pitch);
    joined.set(
      note.pitch,
      first
        ? {
            ...first,
            length:
              Math.max(first.start + first.length, note.start + note.length) -
              first.start,
          }
        : note
    );
  }
  const kept = new Set([...joined.values()].map((note) => note.id));
  return notes.flatMap((note) => {
    if (!ids.has(note.id)) {
      return [note];
    }
    return kept.has(note.id) ? [joined.get(note.pitch) as Note] : [];
  });
}

/**
 * Lengthens or shortens each note in `ids` to end where the next of them
 * starts, so a phrase plays without gaps. The notes that start last reach
 * `end`, such as where the loop ends, or keep their length without one.
 */
export function legatoNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  minLength: number,
  end?: number
): Note[] {
  const starts = [
    ...new Set(
      notes.filter((note) => ids.has(note.id)).map((note) => note.start)
    ),
  ].sort((a, b) => a - b);
  return notes.map((note) => {
    const next =
      starts.find((start) => start > note.start) ??
      (end !== undefined && end > note.start ? end : undefined);
    return ids.has(note.id) && next !== undefined
      ? { ...note, length: Math.max(minLength, next - note.start) }
      : note;
  });
}

/** Plays the notes in `ids` backwards: each lands where it would end, mirrored across their span. */
export function reverseNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>
): Note[] {
  const { chosen, earliest, latestEnd } = span(notes, ids);
  if (chosen.length === 0) {
    return [...notes];
  }
  return notes.map((note) =>
    ids.has(note.id)
      ? { ...note, start: earliest + latestEnd - note.start - note.length }
      : note
  );
}

/** Turns the notes in `ids` upside down: the highest becomes the lowest, around the middle of their range. */
export function invertNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>
): Note[] {
  const chosen = notes.filter((note) => ids.has(note.id));
  if (chosen.length === 0) {
    return [...notes];
  }
  const sum =
    Math.min(...chosen.map((note) => note.pitch)) +
    Math.max(...chosen.map((note) => note.pitch));
  return notes.map((note) =>
    ids.has(note.id) ? { ...note, pitch: sum - note.pitch } : note
  );
}

/**
 * Makes the notes in `ids` `factor` times as long, around `anchor` (where the
 * earliest starts, by default): 2 plays them at half the speed, 0.5 at twice.
 * The factor stops where a note would leave the roll, and no note gets
 * shorter than `minLength`.
 */
export function stretchNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  factor: number,
  bounds: RollBounds,
  anchor?: number
): Note[] {
  const { chosen, earliest, latestEnd } = span(notes, ids);
  if (chosen.length === 0 || !(Number.isFinite(factor) && factor > 0)) {
    return [...notes];
  }
  const origin = anchor ?? earliest;
  const limits = [
    latestEnd > origin
      ? (bounds.duration - origin) / (latestEnd - origin)
      : Number.POSITIVE_INFINITY,
    earliest < origin ? origin / (origin - earliest) : Number.POSITIVE_INFINITY,
  ];
  const scale = Math.min(factor, ...limits);
  return notes.map((note) =>
    ids.has(note.id)
      ? {
          ...note,
          length: Math.max(bounds.minLength, note.length * scale),
          start: origin + (note.start - origin) * scale,
        }
      : note
  );
}

/** The pitch nearest `pitch` whose class is in `classes`: itself when it is, else the lower of two as near. */
function nearestIn(pitch: number, classes: ReadonlySet<number>): number {
  const rounded = Math.round(pitch);
  for (let distance = 0; distance < 12 && classes.size > 0; distance += 1) {
    if (classes.has(pitchClassOf(rounded - distance))) {
      return rounded - distance;
    }
    if (classes.has(pitchClassOf(rounded + distance))) {
      return rounded + distance;
    }
  }
  return rounded;
}

/**
 * Moves each note in `ids` that is out of `scale` to the nearest pitch in it,
 * the lower of two as near. One that would leave the roll stays where it is.
 */
export function fitNotesToScale(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  scale: RollScale,
  bounds: RollBounds
): Note[] {
  const classes = new Set(scale.pitchClasses.map(pitchClassOf));
  return notes.map((note) => {
    if (!ids.has(note.id)) {
      return note;
    }
    const pitch = nearestIn(note.pitch, classes);
    return pitch === note.pitch ||
      pitch < bounds.minPitch ||
      pitch > bounds.maxPitch
      ? note
      : { ...note, pitch };
  });
}

/**
 * Sets the velocity of the notes in `ids` along a line, from `from` on the
 * earliest to `to` on the latest: a crescendo, or a fade.
 */
export function rampVelocity(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  from: number,
  to: number
): Note[] {
  const chosen = notes.filter((note) => ids.has(note.id));
  if (chosen.length === 0) {
    return [...notes];
  }
  const first = Math.min(...chosen.map((note) => note.start));
  const last = Math.max(...chosen.map((note) => note.start));
  return notes.map((note) => {
    if (!ids.has(note.id)) {
      return note;
    }
    const at = last > first ? (note.start - first) / (last - first) : 0;
    return {
      ...note,
      velocity: Math.min(1, Math.max(0, from + (to - from) * at)),
    };
  });
}

/**
 * Loosens the notes in `ids` the way a player would: each start moves by up
 * to `timing` either way and each velocity by up to `velocity`, from
 * `random` (0…1, `Math.random` by default). Notes stay on the roll.
 */
export function humanizeNotes(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  amount: { timing: number; velocity: number },
  bounds: RollBounds,
  random: () => number = Math.random
): Note[] {
  return notes.map((note) => {
    if (!ids.has(note.id)) {
      return note;
    }
    const start = note.start + (random() * 2 - 1) * amount.timing;
    const velocity =
      (note.velocity ?? 1) + (random() * 2 - 1) * amount.velocity;
    return {
      ...note,
      start: Math.min(bounds.duration - note.length, Math.max(0, start)),
      velocity: Math.min(1, Math.max(0, velocity)),
    };
  });
}

/**
 * Deactivates the notes in `ids`, or activates them again when every one of
 * them already is: a deactivated note stays on the roll and does not play.
 */
export function toggleMuted(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>
): Note[] {
  const chosen = notes.filter((note) => ids.has(note.id));
  const muted = !chosen.every((note) => note.muted);
  return notes.map((note) => (ids.has(note.id) ? { ...note, muted } : note));
}

/** Sets how likely the notes in `ids` are to play each time round, 0…1: 1 always, 0.5 every other time on average. */
export function setChance(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>,
  chance: number
): Note[] {
  const value = Math.min(1, Math.max(0, chance));
  return notes.map((note) =>
    ids.has(note.id) ? { ...note, chance: value } : note
  );
}

/** The time the notes in `ids` cover, from the earliest start to the latest end, or null with none. */
export function selectionSpan(
  notes: readonly Note[],
  ids: ReadonlySet<NoteId>
): { end: number; start: number } | null {
  const chosen = notes.filter((note) => ids.has(note.id));
  if (chosen.length === 0) {
    return null;
  }
  return {
    end: Math.max(...chosen.map((note) => note.start + note.length)),
    start: Math.min(...chosen.map((note) => note.start)),
  };
}

/** The notes cut to the clip: those past its end go, those crossing it end there. */
function withinDuration(notes: Note[], duration: number): Note[] {
  return notes
    .filter((note) => note.start < duration)
    .map((note) =>
      note.start + note.length > duration
        ? { ...note, length: duration - note.start }
        : note
    );
}

/**
 * Takes the time from `start` to `end` out of the clip: the notes inside it
 * go, those after it move back by its length, and one crossing it loses the
 * part inside.
 */
export function deleteTime(
  notes: readonly Note[],
  start: number,
  end: number
): Note[] {
  const gap = end - start;
  if (!(gap > 0)) {
    return [...notes];
  }
  const moved = (time: number) => {
    if (time <= start) {
      return time;
    }
    return time >= end ? time - gap : start;
  };
  return notes.flatMap((note) => {
    const from = moved(note.start);
    const to = moved(note.start + note.length);
    return to > from ? [{ ...note, length: to - from, start: from }] : [];
  });
}

/**
 * Opens `length` of silence at `at`: the notes from there on move later by
 * it, one crossing `at` is split there with its second part moved along, and
 * what then runs past the clip's `duration` is cut off.
 */
export function insertTime(
  notes: readonly Note[],
  at: number,
  length: number,
  nextId: () => NoteId,
  duration: number
): Note[] {
  if (!(length > 0)) {
    return [...notes];
  }
  const next = notes.flatMap((note) => {
    const end = note.start + note.length;
    if (note.start >= at) {
      return [{ ...note, start: note.start + length }];
    }
    if (end <= at) {
      return [note];
    }
    return [
      { ...note, length: at - note.start },
      { ...note, id: nextId(), length: end - at, start: at + length },
    ];
  });
  return withinDuration(next, duration);
}

/**
 * Repeats the time from `start` to `end` right after itself: silence opens at
 * `end` and the notes in the range, cut to it, are copied into it under new
 * ids. `added` lists the copies.
 */
export function duplicateTime(
  notes: readonly Note[],
  start: number,
  end: number,
  nextId: () => NoteId,
  duration: number
): { added: NoteId[]; notes: Note[] } {
  const length = end - start;
  if (!(length > 0)) {
    return { added: [], notes: [...notes] };
  }
  const copies = notes.flatMap((note) => {
    const from = Math.max(note.start, start);
    const to = Math.min(note.start + note.length, end);
    return to > from
      ? [{ ...note, id: nextId(), length: to - from, start: from + length }]
      : [];
  });
  const spread = insertTime(notes, end, length, nextId, duration);
  const kept = withinDuration(copies, duration);
  return {
    added: kept.map((note) => note.id),
    notes: [...spread, ...kept],
  };
}

/** What `findNotes` looks for; every condition given must hold. */
export interface NoteQuery {
  /** Chance from…to, 0…1, inclusive. */
  chance?: readonly [number, number];
  /** Of the notes found, in the order they play, every `count`th from the `offset`th (0 is the first). */
  every?: { count: number; offset: number };
  /** Whether to find the notes that do not match instead. */
  invert?: boolean;
  /** Length from…to, in the timeline's units, inclusive. */
  length?: readonly [number, number];
  /** Deactivated notes only, or active ones only. */
  muted?: boolean;
  /** Pitch classes, in any octave: 0 is C, 11 is B. */
  pitchClasses?: readonly number[];
  /** Notes in `scale`, or with `within: false` those out of it. */
  scale?: { scale: RollScale; within: boolean };
  /** Velocity from…to, 0…1, inclusive. */
  velocity?: readonly [number, number];
}

const inRange = (value: number, range?: readonly [number, number]) =>
  !range || (value >= range[0] - 1e-9 && value <= range[1] + 1e-9);

/** Whether a note meets every condition of `query` but its count. */
function matches(note: Note, query: NoteQuery): boolean {
  const pitchClass = pitchClassOf(note.pitch);
  return (
    (!query.pitchClasses || query.pitchClasses.includes(pitchClass)) &&
    inRange(note.velocity ?? 1, query.velocity) &&
    inRange(note.length, query.length) &&
    inRange(note.chance ?? 1, query.chance) &&
    (query.muted === undefined || (note.muted ?? false) === query.muted) &&
    (!query.scale ||
      query.scale.scale.pitchClasses.some(
        (each) => pitchClassOf(each) === pitchClass
      ) === query.scale.within)
  );
}

/**
 * The ids of the notes that match `query`, in the order they play: to select
 * every note of a pitch, a range of velocities or lengths, out of a scale,
 * or every other one.
 */
export function findNotes(notes: readonly Note[], query: NoteQuery): NoteId[] {
  const ordered = spatialOrder(notes);
  let found = ordered.filter((note) => matches(note, query));
  const { every } = query;
  if (every && every.count > 1) {
    found = found.filter(
      (_, index) =>
        index >= every.offset && (index - every.offset) % every.count === 0
    );
  }
  const ids = new Set(found.map((note) => note.id));
  return ordered
    .filter((note) => ids.has(note.id) !== (query.invert ?? false))
    .map((note) => note.id);
}

/**
 * A scale as a piano roll reads it: the pitch classes it keeps and the one it
 * starts on, each from 0 (C) to 11 (B). C major is
 * `{ pitchClasses: [0, 2, 4, 5, 7, 9, 11], root: 0 }`; a scale by name, such
 * as `@audio-ui/engine/pitch`'s, gives its pitch classes.
 */
export interface RollScale {
  pitchClasses: readonly number[];
  root: number;
}

/** A pitch's class, 0 (C) to 11 (B). */
export const pitchClassOf = (pitch: number) =>
  ((Math.round(pitch) % 12) + 12) % 12;

/**
 * The rows a piano roll draws, highest pitch first, and the conversions
 * between a pitch and its row. Folding is nothing but a different list of
 * rows: every part reads its geometry from here.
 */
export interface Rows {
  /** Whether only some pitches are drawn: those carrying notes, or with a scale, those in it too. */
  folded: boolean;
  /** The pitch on `row`, carrying on by semitones past either end. */
  pitchAt: (row: number) => number;
  /** Highest first, which is top to bottom on screen. */
  pitches: readonly number[];
  /** The pitch class of the scale's root, 0 (C) to 11 (B), or null without a scale. */
  root: number | null;
  /** The row `pitch` is drawn on; a pitch with no row of its own sits on the row it would be inserted at. */
  rowOf: (pitch: number) => number;
  /** The pitch classes of the roll's scale, 0 (C) to 11 (B), or null without one. */
  scale: readonly number[] | null;
  /** Where a note at `pitch` lands after moving `rows` rows down (negative is up). */
  step: (pitch: number, rows: number) => number;
}

/** Every pitch from `max` down to `min`. */
function chromatic(
  min: number,
  max: number,
  scale: readonly number[] | null,
  root: number | null
): Rows {
  const pitches: number[] = [];
  for (let pitch = max; pitch >= min; pitch -= 1) {
    pitches.push(pitch);
  }
  return {
    folded: false,
    pitchAt: (row) => max - row,
    pitches,
    root,
    rowOf: (pitch) => max - pitch,
    scale,
    step: (pitch, rows) => pitch - rows,
  };
}

/** Only `pitches` (highest first), continuing by semitones past either end. */
function folded(
  pitches: number[],
  scale: readonly number[] | null,
  root: number | null
): Rows {
  const last = pitches.length - 1;
  const pitchAt = (row: number): number => {
    if (row < 0) {
      return (pitches[0] ?? 0) - row;
    }
    if (row > last) {
      return (pitches[last] ?? 0) - (row - last);
    }
    return pitches[row] ?? 0;
  };
  const rowOf = (pitch: number): number => {
    const found = pitches.indexOf(pitch);
    if (found !== -1) {
      return found;
    }
    const below = pitches.findIndex((other) => other < pitch);
    return below === -1 ? pitches.length : below;
  };
  return {
    folded: true,
    pitchAt,
    pitches,
    root,
    rowOf,
    scale,
    step: (pitch, rows) => pitchAt(rowOf(pitch) + rows),
  };
}

/**
 * The rows for pitches `min` to `max`: every one, or folded to just those
 * the notes use, and with `"scale"` those in `scale` as well. A roll with
 * nothing to fold onto keeps every row.
 */
export function rollRows(
  notes: readonly { pitch: number }[],
  min: number,
  max: number,
  fold: boolean | "scale",
  scale: RollScale | null = null
): Rows {
  const classes = scale
    ? [...new Set(scale.pitchClasses.map(pitchClassOf))].sort((a, b) => a - b)
    : null;
  const root = scale ? pitchClassOf(scale.root) : null;
  if (fold) {
    const kept = new Set(notes.map((note) => note.pitch));
    if (fold === "scale" && classes) {
      for (let pitch = min; pitch <= max; pitch += 1) {
        if (classes.includes(((pitch % 12) + 12) % 12)) {
          kept.add(pitch);
        }
      }
    }
    const pitches = [...kept]
      .filter((pitch) => pitch >= min && pitch <= max)
      .sort((a, b) => b - a);
    if (pitches.length > 0) {
      return folded(pitches, classes, root);
    }
  }
  return chromatic(min, max, classes, root);
}

import { createParts } from "@ui-sdk/web";
import { type PianoRollState, pianoRoll } from "./piano-roll";

/** Makes, or takes away, the children of `parent` named `tag` so there is one for each key, in the order they came. */
function syncChildren(
  parent: Element,
  tag: string,
  keys: readonly string[],
  make: (key: string) => Element
) {
  const wanted = new Set(keys);
  const present = new Map<string, Element>();
  for (const child of [...parent.children]) {
    if (child.localName !== tag || !child.hasAttribute("data-generated")) {
      continue;
    }
    const key = child.getAttribute("data-key") ?? "";
    if (wanted.has(key)) {
      present.set(key, child);
    } else {
      child.remove();
    }
  }
  for (const key of keys) {
    if (!present.has(key)) {
      const element = make(key);
      element.setAttribute("data-generated", "");
      element.setAttribute("data-key", key);
      parent.appendChild(element);
    }
  }
}

/** A part that belongs to a note or a row, with the attribute that names it. */
function part(tag: string, attribute: string, key: string, extra = {}) {
  const element = document.createElement(tag);
  element.setAttribute(attribute, key);
  for (const [name, value] of Object.entries(extra)) {
    element.setAttribute(name, String(value));
  }
  return element;
}

/** What the roll's own containers hold, one for each note or pitch. */
function drawParts(
  el: HTMLElement,
  instance: {
    get: () => object;
    subscribe: (listener: () => void) => () => void;
  }
) {
  const paint = () => {
    const { view } = instance.get() as PianoRollState;
    // The notes keep the order they came in: a note moved past another keeps its place in the DOM, which keeps a drag going.
    for (const notes of el.querySelectorAll("audio-ui-piano-roll-notes")) {
      syncChildren(
        notes,
        "audio-ui-piano-roll-note",
        view.notes.map((note) => String(note.id)),
        (key) => {
          const note = part("audio-ui-piano-roll-note", "note", key);
          if (notes.hasAttribute("handles")) {
            for (const edge of ["start", "end"]) {
              note.appendChild(
                part(`audio-ui-piano-roll-note-${edge}`, "note", key)
              );
            }
          }
          return note;
        }
      );
    }
    for (const rows of el.querySelectorAll("audio-ui-piano-roll-rows")) {
      syncChildren(
        rows,
        "audio-ui-piano-roll-row",
        view.rows.pitches.map(String),
        (key) => part("audio-ui-piano-roll-row", "pitch", key)
      );
    }
    for (const lane of el.querySelectorAll(
      "audio-ui-piano-roll-velocity-lane"
    )) {
      const level = lane.getAttribute("level") ?? "velocity";
      syncChildren(
        lane,
        "audio-ui-piano-roll-velocity",
        view.notes.map((note) => String(note.id)),
        (key) => {
          const bar = part("audio-ui-piano-roll-velocity", "note", key, {
            level,
          });
          const holder = part(
            "audio-ui-piano-roll-velocity-input",
            "note",
            key,
            { level }
          );
          const input = document.createElement("input");
          input.setAttribute("aria-label", `Note ${key}`);
          for (const type of ["input", "change"]) {
            input.addEventListener(type, (event) => event.stopPropagation());
          }
          holder.appendChild(input);
          bar.appendChild(holder);
          return bar;
        }
      );
    }
  };
  paint();
  queueMicrotask(paint);
  // A container written later is drawn into too.
  const observer = new MutationObserver(paint);
  observer.observe(el, { childList: true, subtree: true });
  const unsubscribe = instance.subscribe(paint);
  return () => {
    observer.disconnect();
    unsubscribe();
  };
}

const jsonAttribute = (value: string | null) =>
  value ? JSON.parse(value) : undefined;

const numberAttribute = (value: string | null) =>
  value === null ? undefined : Number(value);

/** `folded` is on, off, or `"scale"`. */
const foldedAttribute = (value: string | null) => {
  if (value === null || value === "false") {
    return;
  }
  return value === "scale" ? "scale" : true;
};

/**
 * The whole web adapter of the piano roll: a tag for each part. The notes, the
 * rows and the velocity bars are made for you, one for each note or pitch.
 */
export const parts = createParts(pianoRoll, {
  grid: { display: "block", tag: "audio-ui-piano-roll-grid" },
  keys: { display: "block", tag: "audio-ui-piano-roll-keys" },
  marquee: { display: "block", tag: "audio-ui-piano-roll-marquee" },
  note: { display: "block", tag: "audio-ui-piano-roll-note" },
  noteEnd: { display: "block", tag: "audio-ui-piano-roll-note-end" },
  noteStart: { display: "block", tag: "audio-ui-piano-roll-note-start" },
  notes: {
    display: "contents",
    tag: "audio-ui-piano-roll-notes",
  },
  root: {
    display: "block",
    events: {
      onNoteOff: "noteoff",
      onNoteOn: "noteon",
      onSelectionChange: "selectionchange",
      onValueChange: "input",
      onValueCommitted: "change",
    },
    kinds: {
      activePitches: jsonAttribute,
      defaultSelection: jsonAttribute,
      defaultValue: jsonAttribute,
      folded: foldedAttribute,
      scale: jsonAttribute,
      selection: jsonAttribute,
      snapPoints: jsonAttribute,
      value: jsonAttribute,
      zoom: numberAttribute,
    },
    // A live position, the label of a note and the id of a new one are set as properties.
    properties: ["createNoteId", "getNoteLabel", "source"],
    render: drawParts,
    tag: "audio-ui-piano-roll",
  },
  row: { display: "block", tag: "audio-ui-piano-roll-row" },
  rows: {
    display: "contents",
    tag: "audio-ui-piano-roll-rows",
  },
  selectionSpan: {
    display: "block",
    tag: "audio-ui-piano-roll-selection-span",
  },
  stretchEnd: { display: "block", tag: "audio-ui-piano-roll-stretch-end" },
  stretchStart: { display: "block", tag: "audio-ui-piano-roll-stretch-start" },
  velocity: { display: "block", tag: "audio-ui-piano-roll-velocity" },
  velocityInput: {
    display: "contents",
    properties: ["getAriaValueText"],
    tag: "audio-ui-piano-roll-velocity-input",
    target: (el) => el.querySelector("input"),
  },
  velocityLane: {
    display: "block",
    tag: "audio-ui-piano-roll-velocity-lane",
  },
});
